COLLDATA("tadabburar","ar",[[170,"§الأعراف\nwords\nهُدنَارَجَعنَا تَائِبِينَ إِلَيكَ.\nالأُمِّيَّالَّذِي لاَ يَقرَأُ، وَلاَ يَكتُبُ.\nإِصرَهُممَا كُلِّفُوهُ مِنَ الأَعمَالِ الشَّاقَّةِ.\nوَعَزَّرُوهُوَقَّرُوهُ، وَعَظَّمُوهُ.\ndeeds\nاقرأ كتابًا، أو مقالًا تتعرف فيه على شمائل النبي وصفاته.\nتذكر سنةً كنت غافلًا عنها من سنن النبي، وطبِّقها.\nدرب نفسك اليوم على الأمر بالمعروف والنهي عن المنكر، ولو على صديقك أو أحد من أهلك.\nguid\nتقوى الله، وأداء الزكاة والصدقات سبب لحصول الرحمة.\nما أحله الله لك؛ فهو الطيب المناسب لك، وما حرمه عليك؛ ففيه المفاسد العاجلة والآجلة.\nمن أراد الهداية العامة والخاصة، العاجلة والآجلة، فليلزم اتباع الحبيب -صلى الله عليه وسلم- بالأدلة الصحيحة.\nrefl\nوَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءٖۚ\nعمت كل شيء؛ قال الحسن وقتادة: \"وسعت رحمته في الدنيا البر والفاجر، وهي يوم القيامة للمتقين خاصة\". البغوي:٢/١٥٧.\nرحمة الله لمن تكون في الدنيا؟ ولمن تكون في الآخر؟\nفَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ ١٥٦\nأي: يؤمنون بجميع الكتب والأنبياء، وليس ذلك لغير هذه الأمّة. ابن جزي:١/٣١٩.\nلم كانت هذه الآية بشارة لهذه الأمة دون غيرها؟\nوَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ ١٥٦\nومن تمام الإيمان بآيات الله: معرفة معناها، والعمل بمقتضاها، ومن ذلك اتباع النبي -صلى الله عليه وسلم- ظاهرًا وباطنًا، في أصول الدين وفروعه. السعدي:٣٠٥.\nما علامات الإيمان بآيات الله؟\nٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ\nفإن أميته لم تكن من جهة فقد العلم والقراءة عن ظهر قلب؛ فإنه إمام الأئمة في هذا، وإنَّما كان من جهة أنه لا يكتب ولا يقرأ مكتوبًا. ابن تيمية:٣/٢١٠.\nمن أي جهة كانت أمية النبي -صلى الله عليه وسلم-؟\nوَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ\nالإصر: الثقل... فإن بني إسرائيل قد كان أخذ عليهم عهدًا أن يقوموا بأعمال ثقال؛ فوضع عنهم بمحمد -صلى الله عليه وسلم- ذلك العهد، وثقل تلك الأعمال؛ كغسل البول، وتحليل الغنائم، ومجالسة الحائض، ومؤاكلتها. القرطبي:٩/٣٥٦.\nبيّن عظيم رحمة الله تعالى بهذه الأمة حيث وضع عنها الآصار والأثقال.\nفَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ١٥٧\n﴿فَٱلَّذِينَ ءَامَنُواْ بِهِۦ﴾ أي: بمحمد -صلى الله عليه وسلم- (وعزروه): وقَّروه، (ونصروه): على الأعداء، ﴿وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ﴾: يعني: القرآن، ﴿أُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾. البغوي:٢/٣١٥٩.\nما صفات المفلحين في كتاب الله تعالى؟\nوَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ١٥٩\nوكأن الإتيان بهذه الآية الكريمة فيه نوع احتراز مما تقدم؛ فإنه تعالى ذكر فيما تقدم جملةً من معايب بني إسرائيل المنافية للكمال، المناقضة للهداية، فرُبَّمَا توهم متوهم أن هذا يعم جميعَهم، فذكر تعالى أن منهم طائفةً مستقيمة، هاديةً مَهدِيَّةً. السعدي:٣٠٦.\nما وجه الإتيان بمدح طائفة من قوم موسى في سياق الآيات التي تذمهم؟"],[171,"§الأعراف\nwords\nوَقَطَّعنَاهُمُفَرَّقنَاهُم.\nفَانبَجَسَتفَانفَجَرَت، الاِنبِجَاسُ أَوَّلُ الاِنفِجَارِ.\nيَعدُونَ فِي السَّبتِيَعتَدُونَ بِالصَّيدِ فِي يَومِ السَّبتِ، وَهُوَ مُحَرَّمٌ عَلَيهِم.\nشُرَّعًاظَاهِرَةً عَلَى وَجهِ المَاءِ.\nلاَ يَسبِتُونَفِي غَيرِ يَومِ السَّبتِ.\ndeeds\nتدرب على الترتيب، وضع جدولًا أسبوعيًا لأعمالك واحتياجاتك.\nاستبدل بالطعام المشتبه به طعامًا حلالًا؛ فللطعام أثر على العبادة، والتفكير، والسلوك.\nاقرأ قصة أصحاب السبت، وتعلّم منها خطورة التحايل على شرع الله.\nguid\nإذا أنعم الله على عبد أو أمة نعمة ولم يشكرها سلبت منه.\nالفسق والمعاصي سببٌ لحصول ابتلاءاتٍ قد لا يستطيع الإنسان الثبات فيها.\nإذا وجدت البلاء نزل بك؛ فتذكر معصية فعلتها ثم أكثر من الاستغفار منها.\nrefl\nوَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ١٦٠\n﴿وَمَا ظَلَمُونَا﴾ حين لم يشكروا الله، ولم يقوموا بما أوجب الله عليهم، ﴿وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ﴾؛ حيث فوّتوها كل خير، وعرّضوها للشر والنقمة. السعدي:٣٠٦.\nبينت الآية نوعًا من أنواع ظلم النفس، فما هو؟\nفَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ ١٦٢\nووقع في هذه الآية: ﴿فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ﴾، ولم يقع لفظ: (منهم) في سورة البقرة، ووجه زيادتها هنا: التصريح بأن تبديل القول لم يصدر من جميعهم، وأجمل ذلك في سورة البقرة؛ لأن آية البقرة لمَّا سيقت مساق التوبيخ ناسب إرهابهم بما يوهم أن الذين فعلوا ذلك هم جميع القوم؛ لأن تبعات بعض القبيلة تحمل على جماعتها. ابن عاشور:٩/١٤٥.\nلماذا جاء لفظ (منهم) في الآية الكريمة، ولم يأت في آية سورة البقرة؟\nفَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ\nوإذا بَدَّلُوا القول مع يسره وسهولته؛ فتبديلهم للفعل من باب أولى. السعدي:٣٠٦.\nفي الآية إشارةٌ إلى تعود ظَلَمَةِ اليهود على مخالفة الأوامر الربَّانِيَّة، وضِّح ذلك.\nفَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ ١٦٢\nإذا أنعم الله على عبد أو أمة نعمة ثم لم يشكرها تسلب منه أحب أم كره وكائنًا من كان. الجزائري:٢/٢٥٢.\nبيّن خطورة عدم شكر النعمة من خلال الآية.\nوَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ ١٦٣\nفي هذه الآية مزجرة عظيمة للمتعاطين الحيل على المناهي الشرعية، ممن يتلبس بعلم الفقه وليس بفقيه؛ إذ الفقيه من يخشى الله تعالى؛ في الربويات، والتحليل باستعارة المحلل للمطلقات، والخلع لحلّ ما لزم من المطلقات المعلقات، إلى غير ذلك من عظائم ومصائب؛ لو اعتمد بعضها مخلوق في حق مخلوق لكان في نهاية القبح، فكيف في حق من يعلم السر وأخفى؟! ابن تيمية:٣/٢١٥.\nفي ضوء الآية الكريمة: بيّن خطورة التحايل على الشريعة.\nوَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ ١٦٣\nفأخبر أنه بلاهم بفسقهم؛ حيث أتى بالحيتان يوم التحريم، ومنعها يوم الإباحة؛ كما يؤتى المحرم المبتلى بالصيد يوم إحرامه، ولا يؤتى به يوم حله، أو يؤتى بمن يعامله ربًا، ولا يؤتى بمن يعامله بيعًا. ابن تيمية:٣/٢١٥.\nبيّن كيف كان فسق أهل القرية سببًا في ابتلائهم.\nوَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ\nوكانوا يقولون: نحن أبناء الله وأحباؤه؛ لأنّا من سبط خليله إبراهيم، ومن سبط إسرائيل وهم بكر الله، ومن سبط موسى كليم الله، ومن سبط ولده عُزير؛ فنحن من أولادهم، فقال الله -عز وجل- لنبيه: سلهم يا محمد عن القرية: أما عذبتهم بذنوبهم؟ وذلك بتغيير فرع من فروع الشريعة. القرطبي:٩/٣٦٢.\nالقرابة من الأنبياء لا تمنع عقوبة الله سبحانه لمن عصى، وضح ذلك من الآية."],[172,"§الأعراف\nwords\nبَئِيسٍشَدِيدٍ.\nعَتَوااستَكبَرُوا، وَعَصَوا.\nخَاسِئِينَأَذِلاَّءَ، مُبعَدِينَ.\nيَسُومُهُميُذِيقُهُم.\nعَرَضَ هَذَا الأَدنَىمَا يُعرَضُ لَهُم مِن دَنِيءِ المَكَاسِبِ؛ كَالرِّشوَةِ.\nوَدَرَسُوا مَا فِيهِعَلِمُوا مَا فِي الكِتَابِ، فَضَيَّعُوهُ.\ndeeds\nقل: \"اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك\".\nاقرأ سورة من قصار المفصل، وطبق ما فيها من أعمال.\nحافظ على الصلوات المفروضة مع الجماعة.\nguid\nالمثبطون عن قول الحق موجودون في كل زمان ومكان؛ فاحذرهم.\nلا تنسَ ولا تتهاون في الأخذ بنصيحة من يعظك ويذكرك بالله.\nتحسن أحوالك أو سوؤها ابتلاءٌ من الله -سبحانه وتعالى-؛ فارتبط بالله أكثر عند تغيرها.\nrefl\nوَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ ١٦٤\nافترقت بنو إسرائيل ثلاث فرق: فرقة عصت يوم السبت بالصيد، وفرقة نهت عن ذلك واعتزلت القوم، وفرقة سكتت واعتزلت؛ فلم تنه ولم تعص. وأن هذه الفرقة لمَّا رأت مهاجرة الناهية وطغيانَ العاصية قالوا للفرقة الناهية: لم تعظون قومًا يريد الله أن يهلكهم أو يعذبهم؟ فقالت الناهية: نَنهاهم معذرة إلى الله، ولعلهم يتقون. فهلكت الفرقة العاصية، ونجت الناهية، واختلف في الثالثة؛ هل هلكت لسكوتها، أو نجت لاعتزالها وتركها العصيان؟ ابن جزي:١/٣٢٦.\nينقسم الناس عند انتشار المنكر إلى ثلاثة أقسام؛ ما هي؟ وما مصير كل قسم؟\nوَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ ١٦٤\nوهذا المقصود الأعظم من إنكار المنكر؛ ليكون معذرة، وإقامة حجة على المأمور المنهي، ولعل الله أن يهديه؛ فيعمل بمقتضى ذلك الأمر والنهي. السعدي:٣٠٧.\nما المقصود الأعظم من الأمر بالمعروف والنهي عن المنكر؟\nفَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ\nوهكذا سنة الله في عباده: أن العقوبة إذا نزلت نجا منها الآمرون بالمعروف والناهون عن المنكر. السعدي:٣٠٧.\nما الفائدة الدنيوية التي تعود على الآمرين بالمعروف الناهين عن المنكر؟\nإِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٞ ١٦٧\nوهذا من باب قرن الرحمة مع العقوبة؛ لئلَّا يحصل اليأس؛ فيقرن تعالى بين الترغيب والترهيب كثيرًا؛ لتبقى النفوس بين الرجاء والخوف. ابن كثير:٢/٢٤٩.\nلماذا يقرن تعالى بين الرحمة والعذاب؟\nوَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ ١٦٨\n﴿وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ﴾: بالخصب والعافية، (والسيئات): الجدب والشدة، ﴿لَعَلَّهُمۡ يَرۡجِعُونَ﴾: لكي يرجعوا إلى طاعة ربهم ويتوبوا. البغوي:٢/١٦٤.\nما الحكمة من نزول البلاء بالنعم والنقم؟\nأَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ\n﴿وَدَرَسُواْ مَا فِيهِۗ﴾: فليس عليهم فيه إشكال، بل قد أَتَوا أمرهم متعمدين، وكانوا في أمرهم مستبصرين؛ وهذا أعظم للذنب، وأشد للوم، وأشنع للعقوبة. السعدي:٣٠٧.\nما الفرق بين معصية من يعلم ومعصية الجاهل؟\nوَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ ١٧٠\n(يُمَسِّكون): فيها معنى التكرير والتكثير للتمسك بكتاب الله تعالى وبدينه، فبذلك يمدحون؛ فالتمسك بكتاب الله والدين يحتاج إلى الملازمة والتكرير. القرطبي:٩/٣٧٤.\nلماذا شُدد الفعل (يُمَسِّكون) حينما أضافه لكتاب الله تعالى؟"],[173,"§الأعراف\nwords\nنَتَقنَارَفَعنَا.\nظُلَّةٌسَحَابَةٌ.\nذُرِّيَّةًصِغَارًا.\nفَأَتبَعَهُ الشَّيطَانُلَحِقَهُ، وَصَارَ قَرِينَهُ، وَاستَحوَذَ عَلَيهِ.\nأَخلَدَ إِلَى الأَرضِرَكَنَ إِلَى الدُّنيَا، وَرَضِيَ بِهَا.\nتَحمِل عَلَيهِتَطرُدهُ.\ndeeds\nألق كلمةً في حلقة القرآن، أو أرسل رسالةً عن خطورة تعلم العلم أو حفظ القرآن لغير وجه الله تعالى.\nاقرأ من كتب التفسير قصة الرجل الذي تكلمت عنه الآية، ثم استخرج أهم فوائدها.\nتجنب اليوم كل أمر يشغلك عن كتاب الله تعالى.\nguid\nمن أسباب التقوى: أخذ الكتاب وأحكامه بقوة واجتهاد، ومدارسة ما فيه.\nذكر القصص أسلوبٌ دعويٌ ناجعٌ أمر به الله سبحانه.\nالهداية والإضلال بيد الله سبحانه؛ فاسأل الله الهداية.\nrefl\nأَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ ءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ ١٧٣\nفقد أودع الله في فِطَرِكم ما يدلكم على أن ما مع آبائكم باطل، وأن الحق ما جاءت به الرسل، وهذا يقاوم ما وجدتم عليه آباءكم، ويعلو عليه. نعم... قد يعرض للعبد من أقوال آبائه الضالين ومذاهبهم الفاسدة ما يظنه هو الحق، وما ذاك إلا لإعراضه عن حجج الله وبيناته وآياته الأفقية والنفسية؛ فإعراضه عن ذلك وإقباله على ما قاله المبطلون ربما صيّره بحالة يفضل بها الباطل على الحق. السعدي:٣٠٨.\nلماذا يتبع بعض الناس آراء آبائهم ويترك ما جاء به المرسلون؟\nوَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ ١٧٥\nانسلخ من الاتصاف الحقيقي بالعلم بآيات الله؛ فإن العلم بذلك يصير صاحبه متصفًا بمكارم الأخلاق ومحاسن الأعمال، ويرقى إلى أعلى الدرجات وأرفع المقامات. فترك هذا كتاب الله وراء ظهره، ونبذ الأخلاق التي يأمر بها الكتاب، وخلعها كما يخلع اللباس. فلما انسلخ منها أتبعه الشيطان؛ أي: تسلط عليه حين خرج من الحصن الحصين، وصار إلى أسفل سافلين، فأزّه إلى المعاصي أزًّا ﴿فَكَانَ مِنَ ٱلۡغَاوِينَ﴾ بعد أن كان من الراشدين المرشدين. السعدي:٣٠٩.\nما خطورة ترك التمسك بكتاب الله -سبحانه وتعالى- بعد دراسته وعلم ما فيه؟\nوَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ ١٧٥\nلما عاند ولم يعمل بما هداه الله إليه حصلت في نفسه ظلمة شيطانية مكنت الشيطان من استخدامه، وإدامة إضلاله؛ فالانسلاخ على الآيات أثر من وسوسة الشيطان، وإذا أطاع المرء الوسوسة تمكن الشيطان من مقاده فسخره وأدام إضلاله، وهو المعبر عنه ب (فَأَتبَعَهُ) فصار بذلك في زمرة الغواة المتمكنين من الغواية. ابن عاشور:٩/١٧٦.\nما خطورة الاستسلام لوساوس الشيطان؟\nوَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ ١٧٥ وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ\nوفي هذه الآيات: الترغيب في العمل بالعلم، وأن ذلك رفعة من الله لصاحبه، وعصمة من الشيطان، والترهيب من عدم العمل به، وأنه نزول إلى أسفل سافلين، وتسليط للشيطان عليه، وفيه أن اتباع الهوى وإخلاد العبد إلى الشهوات يكون سببًا للخذلان. السعدي:٣٠٨.\nمن خلال الآيات: ما أهمية العمل بالعلم؟\nوَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ\nوقوله تعالى: ﴿وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا﴾ أفاد أن تلك الآيات شأنها أن تكون سببًا للهداية والتزكية لو شاء الله له التوفيق وعصمه من كيد الشيطان وفتنته فلم ينسلخ عنها. وهذه عبرة للموفقين؛ ليعلموا فضل الله عليهم في توفيقهم؛ فالمعنى: ولو شئنا لزاد في العمل بما آتيناه من الآيات فلرفعه الله بعلمه. ابن عاشور:٩/١٧٦.\nآيات القرآن الكريم سبب للهداية، بين ذلك.\nفَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ\nقال القتيبي: كل شيء يلهث إنَّما يلهث من إعياء أو عطش، إلا الكلب؛ فإنه يلهث في حال الكلال، وفي حال الراحة، وفي حالة العطش؛ فضربه الله مثلًا لمن كذب بآياته، فقال: إن وعظته فهو ضال، وإن تركته فهو ضال؛ كالكلب: إن طردته يلهث، وإن تركته على حاله يلهث. البغوي:٢/١٧٥.\nلماذا شبه من يُوعظ ولم يتعظ بالكلب؟\nمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ وَمَن يُضۡلِلۡ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ١٧٨\nوفيها تنويه بشأن المهتدين وتلقين للمسلمين للتوجه إلى الله تعالى بطلب الهداية منه والعصمة من مزالق الضلال. ابن عاشور:٩/١٨٠.\nدلت الآية الكريمة أنه ينبغي التوجه إلى الله تعالى بطلب الهداية، كيف ذلك؟"],[174,"§الأعراف\nwords\nذَرَأنَاخَلَقنَا.\nيَعدِلُونَيَقضُونَ، وَيَحكُمُونَ.\nوَأُملِي لَهُمأُمهِلُهُم.\nيَعمَهُونَيَتَحَيَّرُونَ، وَيَتَرَدَّدُونَ.\nأَيَّانَ مُرسَاهَامَتَى وُقُوعُهَا.\nحَفِيٌّ عَنهَاحَرِيصٌ عَلَى العِلمِ بِهَا.\ndeeds\nاسأل الله تعالى صلاح قلبك، وأن يمتعك بسمعك وبصرك في طاعته.\nقل: \"اللهم أرني الحق حقًّا وارزقني اتباعه\".\nتعرف على معاني أسماء الله الحسنى، ثم ادعُ الله تعالى بها في مظان الإجابة؛ كأن تقول: يا رحيم ارحمني، يا شكور اقبل عملي.\nguid\nاستعمل جوارحك فيما خلقت له.\nاحذر مكر الله -سبحانه وتعالى- فيما أنعم به عليك.\nلا تغتر برؤية العاصي بعافية ومظهر حسن؛ فربما كان هذا استدراجًا له.\nrefl\nلَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ١٧٩\nليس المعنى نفي السمع والبصر جملة، وإنَّما المعنى نفيها عما ينفع في الدين. ابن جزي:١/٣٣٠.\nمتى تعتبر مستفيدًا من سمعك وبصرك في أمر الآخرة؟\nلَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ١٧٩\nلأنهم لا يهتدون إلى ثواب، فهم كالأنعام؛ أي: همتهم الأكل والشرب، وهم أضل؛ لأن الأنعام تبصر منافعها ومضارها، وتتبع مالكها، وهم بخلاف ذلك. القرطبي:٩/٣٩٠.\nلماذا كان بعض بني آدم أضل من الأنعام؟\nوَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ\nسمى الله سبحانه أسماءه بالحسنى؛ لأنها حسنة في الأسماع والقلوب؛ فإنها تدل على توحيده، وكرمه، وجوده، ورحمته، وإفضاله. القرطبي:٩/٣٩٣.\nلم سمى الله تعالى أسماءه بالحسنى؟\nوَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ\nأي: اطلبوا منه بأسمائه؛ فيطلب بكل اسم ما يليق به؛ تقول: يا رحيم ارحمني، يا حكيم احكم لي. القرطبي:٩/٣٩٣.\nكيف يدعو المؤمن ربه بأسمائه الحسنى؟\nوَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ ١٨٠\nوالمراد من ترك الذين يلحدون في أسمائه: الإمساك عن الاسترسال في محاجتهم؛ لظهور أنهم غير قاصدين معرفة الحق، أو: ترك الإصغاء لكلامهم؛ لئلَّا يفتنوا عامة المؤمنين بشبهاتهم. ابن عاشور:٩/١٨٩.\nما المراد من ترك الذين يلحدون في أسمائه سبحانه؟\nوَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ ١٨١\nفدلت الآية على أن الله -عز وجل- لا يخلي الدنيا في وقت من الأوقات من داعٍ يدعو إلى الحق. القرطبي:٩/٣٩٧.\nهل يخلو زمان من قائم لله تعالى بالدعوة إلى دينه؟\nوَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ١٨٢ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ ١٨٣\nقال الكلبي: \"يزين لهم أعمالهم ويهلكهم\"، وقال الضحاك: \"كلما جددوا معصية جددنا لهم نعمة\"، قال سفيان الثوري: \"نسبغ عليهم النعم، وننسيهم الشكر\". البغوي:٢/١٧٦.\nكيف يكون الاستدراج للناس من حيث لا يعلمون؟"],[175,"§الأعراف\nwords\nلِيَسكُنَلِيَأنَسَ، وَيَطمَئِنَّ.\nتَغَشَّاهَاجَامَعَهَا.\nفَمَرَّت بِهِقَامَت بِهِ، وَقَعَدَت؛ لِخِفَّةِ الحَملِ.\nأَثقَلَتصَارَت ثَقِيلَةً لِأَجلِ الحَملِ.\nفَتَعَالَىتَعَاظَمَ، وَتَنَزَّهَ.\ndeeds\nبشِّر من حولك بما عند الله من الخير؛ كأن تبشرهم بقرب نصر الله تعالى وفرجه، وجنته وكرامته لأهل طاعته.\nقل: \"اللهم إني أعوذ بك أن أشرك بك شيئًا وأنا أعلم، وأستغفرك لما لا أعلم\".\nحاور بعض من يلتجئ في قضاء حاجته إلى غير الله تعالى من قبر أو مشهد، وبين له ضعفهم.\nguid\nلو كان القائمون على الأضرحة والقبور صادقين ما أصابهم الضر.\nمن مهام النبي البشارة والنذارة، فاجعلها من مهامك في حياتك.\nإذا حصلت لك نعمة فاشكر الله سبحانه قبل شكر غيره من البشر.\nrefl\nقُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ\n﴿قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعًا﴾ أي: لا أقدر لنفسي نفعًا؛ أي: اجتلاب نفع بأن أربح، ﴿وَلَا ضَرًّا﴾ أي: دفع ضر. البغوي:٢/١٧٨.\nكيف تصحح اعتقاد من يطلب الحاجات من النبي -صلى الله عليه وسلم-؟\nإِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ ١٨٨\nوخص بهم البشارة والنذارة؛ لأنهم هم الذين ينتفعون بها. ابن جزي:١/٣٣٢.\nما وجه اختصاص البشارة والنذارة بأهل الإيمان؟\nفَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ١٨٩ فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ\n(فلما آتاهما صالحًا): على وفق ما طلبا، وتمت عليهما النعمة فيه، (جعلا له شركاء فيما آتاهما) أي: جعلا لله شركاء في ذلك الولد الذي انفرد الله بإيجاده والنعمة به، وأقرَّ به أعين والديه، فَعَبَّدَاه لغير الله؛ إما أن يسمياه بعبد غير الله؛ كـ \"عبد الحارث\" و\"عبد العزير\" و\"عبد الكعبة\" ونحو ذلك، أو يشركا بالله في العبادة، بعدما منَّ الله عليهما بما منَّ من النعم التي لا يحصيها أحد من العباد. السعدي:٣١١.\nاذكر صورتين لكفر نعمة الذرية.\nفَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ١٨٩ فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ\nثم أوجد الذرية في بطون الأمهات وقتًا موقوتًا؛ تتشوف إليه نفوسهم، ويدعون الله أن يخرجه سويًّا صحيحًا، فأتم الله عليهم النعمة وأنالهم مطلوبهم، أفلا يستحق أن يعبدوه، ولا يشركوا به في عبادته أحدًا، ويخلصوا له الدين؟! ولكن الأمر جاء على العكس؛ فأشركوا بالله (ما لا يخلق شيئًا وهم يخلقون * ولا يستطيعون لهم) أي: لعابديها ﴿نَصۡرًا وَلَآ أَنفُسَهُمۡ يَنصُرُونَ﴾. السعدي:٣١١.\nاذكر مثالًا لجهل المشركين وكفرهم من خلال الآية.\nأَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ ١٩٥\nثم وبخهم الله تعالى وسفه عقولهم، فقال: ﴿أَلَهُمۡ أَرۡجُلٌ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٍ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٌ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٌ يَسۡمَعُونَ بِهَاۗ﴾... الآية؛ أي: أنتم أفضل منهم، فكيف تعبدونهم؟! والغرض بيان جهلهم. القرطبي، ٩/٤١٦.\nمن خلال هذه الآية بأي شيء فضلنا الله تعالى على المشركين؟\nأَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ ١٩٥\nوخص الأرجل والأيدي والأعين والآذان؛ لأنها آلات العلم، والسعي، والدفع للنصر. ابن عاشور:٩/٢٢٢.\nلماذا خصت الأرجل والأيدي والأعين والآذان بالذكر في الآية الكريمة؟\nقُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ ١٩٥\nالمعنى: استنجدوا أصنامكم لمضرتي والكيد عليّ، ولا تؤخروني؛ فإنكم وأصنامكم لا تقدرون على مضرتي. ومقصد الآية الرد عليهم ببيان عجز أصنامهم وعدم قدرتها على المضرة، وفيها إشارة إلى التوكل على الله والاعتصام به وحده، وأن غيره لا يقدر على شيء. ابن جزي:١/٣٣٣.\nما علامة بطلان الدعاء والاستغاثة بغير الله فيما لا يقدر عليه إلا الله سبحانه؟"],[176,"§الأعراف\nwords\nخُذِ العَفوَخُذ مَا تَيَسَّرَ مِن أَخلاَقِ النَّاسِ، وَلاَ تُكَلِّفهُم مَا لاَ يُرِيدُونَ بَذلَهُ لَكَ.\nيَنزَغَنَّكَيُصِيبَنَّكَ.\nنَزغٌوَسوَسَةٌ، وَتَثبِيطٌ عَنِ الخَيرِ، وَحَثٌّ عَلَى الشَّرِّ.\nطَائِفٌ مِنَ الشَّيطَانِعَارِضٌ مِن وَسوَسَةِ الشَّيطَانِ.\nلاَ يُقصِرُونَلاَ يَدَّخِرُونَ وُسعًا فِي غَوَايَتِهِم.\ndeeds\nردد هذه الآية، ولتكن على لسانك عند نزول المحن والأزمات.\nسامح شخصًا أساء إليك.\nقل: \"أعوذ بالله من الشيطان الرجيم\" كلما شعرت بوساوس الشيطان.\nguid\nالإسلام عقيدة وأخلاق ومعاملات.\nشؤم أخوة شياطين الأنس؛ حيث لا يقصرون بمد صاحبهم بالغي الذي هو الشر والفساد.\nإذا أحسست بتثبيط عن الخير، أو حث على الشر؛ فهذه وسوسة شيطان فعليك بالاستعاذة بالله منه.\nrefl\nوَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ ١٩٦\nفالمؤمنون الصالحون لمَّا تولوا ربهم بالإيمان والتقوى، ولم يتولوا غيره ممن لا ينفع ولا يضر، تولاهم الله، ولطف بهم، وأعانهم على ما فيه الخير والمصلحة لهم في دينهم ودنياهم، ودفع عنهم بإيمانهم كل مكروه. السعدي:٣١٢.\nكيف يدخل الإنسان في زمرة من يتولاه الله -سبحانه وتعالى- بحفظه ورعايته؟\nوَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ ١٩٩\nإذا تسفه عليك أحد فلا تقابله بالسفه. البغوي:٢/١٨٤.\nلو أن رجلًا شتمك، أو نال منك بغير حق، فماذا تفعل؟\nوَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ ٢٠٠\nنزغ الشيطان: وسوسته بالتشكيك في الحق، والأمر بالمعاصي، أو تحريك الغضب؛ فأمر الله بالاستعاذة منه عند ذلك، كما ورد في الحديث: أن رجلًا اشتد غضبه فقال رسول الله -صلى الله عليه وسلم-: «إني لأعلم كلمة لو قالها لذهب عنه ما به: نعوذ بالله من الشيطان الرجيم». ابن جزي:١/٣٣٥.\nمثّل لبعض نزغات الشيطان.\nوَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ ٢٠٠\n﴿فَٱسۡتَعِذۡ بِٱللَّهِۚ﴾ أي: اطلب النجاء من ذلك بالله؛ فأمر تعالى أن يدفع الوسوسة بالالتجاء إليه، والاستعاذة به. القرطبي:٩/٤٢٣.\nكيف يدفع المؤمن وساوس الشيطان كما أرشدنا القرآن؟\nإِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ ٢٠١\nأي: يبصرون مواقع خطاياهم بالتذكر والتفكر، قال السدي: \"إذا زلوا تابوا\". البغوي:٢/١٨٥.\nكيف يكون حال المؤمن إذا وقع في المعصية؟\nإِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ ٢٠١\nقال سعيد بن جبير: \"هو الرجل يغضب الغضبة فيذكر الله؛ فيكظم الغيظ\"، وقال ليث عن مجاهد: \"هو الرجل يهم بالذنب فيذكر الله؛ فيدعه\". ابن تيمية:٣/٢٣٩.\nمن الذين ﴿إِذَا مَسَّهُمۡ طَٰٓئِفٌ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ﴾؟\nوَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ٢٠٥\nوهذه من الآداب التي ينبغي للعبد أن يراعيها حق رعايتها؛ وهي: الإكثار من ذكر الله آناء الليل والنهار -خصوصًا طَرَفَيِ النهار- مخلصًا خاشعًا متضرعًا، متذلِّلًا ساكنًا، متواطئًا عليه قلبه ولسانه، بأدب ووقار، وإقبال على الدعاء والذكر، وإحضار له بقلبه وعدم غفلة؛ فإن الله لا يستجيب دعاء من قلب غافلٍ لاهٍ. السعدي:٣١٤.\nدلت الآية على سبب مهم من أسباب قبول الدعاء والذكر، فما هو؟"],[177,"§الأنفال\nwords\nالأَنفَالِالغَنَائِمِ.\nوَجِلَتفَزِعَت.\nذَاتِ الشَّوكَةِصَاحِبَةِ السِّلاَحِ، وَالقُوَّةِ.\nدَابِرَ الكَافِرِينَآخِرَهُم، وَالمُرَادُ: جَمِيعُهُم.\ndeeds\nاسع في صلح بين شخصين من المسلمين اختلفا.\nاقرأ من كتب التفسير أو السيرة عن سبب نزول هذه الآيات.\nحاسب نفسك على صلاتك، وانظر في أي جانب قصرت فيها، سواءً كان في أركانها أو واجباتها أو مستحباتها، ثم سد هذا النقص والخلل.\nguid\nمن صفات المؤمنين التوكل على الله، وعدم التوكل على غيره.\nيولي القرآن الكريم إصلاح ذات البين عناية قصوى؛ فقد ورد الأمر به مسبوقًا بأمر عام بتقوى الله، وأعقبه بأمر عام بطاعة الله ورسوله، مع جعله من شروط الإيمان.\nتأمل كيف سمى الله تعالى قتال أعدائه ومناجزتهم حقًّا، خلافًا لمن يسميه بأسماء مشوهة.\nrefl\nيَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ ١\nو(أطيعوا الله ورسوله إن كنتم مؤمنين) يريد في الحكم في الغنائم؛ قال عبادة بن الصامت: \"نزلت فينا أصحاب بدر حين اختلفنا وساءت أخلاقنا، فنزع الله الأنفال من أيدينا، وجعلها لرسول الله -صلى الله عليه وسلم- قسمها على السواء، فكانت في ذلك تقوى الله، وطاعة رسوله، وإصلاح ذات البين\". ابن جزي:١/ ٣٣٨.\nفي هذه الجملة تربية للأمة، وضح ذلك.\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ\nوهذه صفة المؤمن حق المؤمن؛ الذي إذا ذكر الله وجل قلبه؛ أي: خاف منه، ففعل أوامره، وترك زواجره... قال سفيان الثوري: سمعت السدي يقول: \"هو الرجل يريد أن يظلم -أو قال: يهم بمعصية- فيقال له: اتق الله؛ فَيَجِلُ قلبه\". ابن كثير:٢/٢٧٤.\nما الغاية من خوف القلوب من الله سبحانه؟\nوَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا\nووجه ذلك: أنهم يلقون له السمع، ويحضرون قلوبهم لتدبره، فعند ذلك يزيد إيمانهم؛ لأن التدبر من أعمال القلوب، ولأنه لا بد أن يبين لهم معنى ما كانوا يجهلونه، أو يتذكرون ما كانوا نسوه، أو يحدث في قلوبهم رغبة في الخير، واشتياقًا إلى كرامة ربهم، أو وجلًا من العقوبات، وازدجارًا عن المعاصي، وكل هذا مما يزداد به الإيمان. السعدي:٣١٥.\nكيف يزيد التدبر في إيمان الشخص؟\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٢ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣\nقدم تعالى أعمال القلوب؛ لأنها أصل لأعمال الجوارح، وأفضل منها. السعدي:٣١٥.\nلِمَ قَدَّم الله تعالى أعمال القلوب على أعمال الجوارح؟\nٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣\nوجيء بالفعلين المضارعين في (يقيمون) و(ينفقون) للدلالة على تكرر ذلك وتجدده. ابن عاشور:٩/٢٦٠.\nلماذا جيء بالفعلين المضارعين في (يقيمون) و(ينفقون)؟\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ٢ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣ أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ٤\n(أولئك) الموصوفون بهذه الصفات الخمس ﴿هُمُ ٱلۡمُؤۡمِنُونَ حَقًّاۚ﴾ وصدقًا، ﴿لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ﴾ أي: منازل عالية، متفاوتة العلو والارتفاع في الجنة، ولهم قبل ذلك (مغفرة) كاملة لذنوبهم. الجزائري:٢/٢٨٤.\nذكرت الآيات صفات المؤمنين حقًّا، بيّنها باختصار.\nوَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ ٧\nفوعد الله المؤمنين إحدى الطائفتين، إما أن يظفروا بالعير، أو بالنفير؛ فأحبوا العير لقلة ذات يد المسلمين، ولأنها غير ذات شوكة، ولكن الله تعالى أحب لهم وأراد أمرًا أعلى مما أحبوا؛ أراد أن يظفروا بالنفير الذي خرج فيه كبراء المشركين وصناديدهم؛ ﴿وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ﴾ فينصر أهله ﴿وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ﴾ أي: يستأصل أهل الباطل، ويُرِيَ عباده من نصره للحق أمرًا لم يكن يخطر ببالهم. السعدي:٣١٦.\nما الذي ينبغي أن يظنه المسلم إذا أراد الله وقدر غير ما يريده هو ويهواه؟"],[178,"§الأنفال\nwords\nيُغَشِّيكُمُيُلقِي النُّعَاسَ عَلَيكُم؛ كَالغِطَاءِ.\nأَمَنَةًأَمَانًا.\nرِجزَ الشَّيطَانِوَسَاوِسَهُ وَتَخوِيفَاتِهِ.\nمُتَحَرِّفًا لِقِتَالٍمُظهِرًا الفِرَارَ؛ خِدعَةً، ثُمَّ يَكُرُّ.\nمُتَحَيِّزًا إِلَى فِئَةٍمُنحَازًا إِلَى جَمَاعَةِ المُسلِمِينَ، سَوَاءٌ كَانُوا سَرِيَّةً فَانحَازُوا لِلجَيشِ أَوِ انحَازُوا لِلإِمَامِ الأَعظَمِ.\ndeeds\nألحّ على الله تعالى بطلب حاجة من حاجاتك؛ فإن الله يحب الاستغاثة به، والتضرع إليه.\nابحث عن الأخبار السارة عن الدعوة والإغاثة والجهاد وانشرها؛ ففيها بشارة للمؤمنين وتطمين لقلوبهم.\nزُرْ من يؤدي أعمالًا خيريةً لتثبيته وتشجيعه، أو أرسل له رسالةً بذلك.\nguid\nقوة القلب أهم من قوة الجسد؛ فاعمل على تقوية قلبك بالإيمان بالله، وعدم الخوف من الناس.\nمن جند الله تعالى الخفية: (الرعب) يلقيه في قلوب الكفار رغم قوة عددهم وعتادهم.\nإذا ابتدأ المؤمن بعمل صالح ينصر به دين الله تعالى فلا يتراجع ويتخاذل عنه.\nrefl\nوَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ\n﴿وَمَا جَعَلَهُ ٱللَّهُ﴾ أي: إنزال الملائكة، ﴿إِلَّا بُشۡرَىٰ﴾ أي: لتستبشر بذلك نفوسكم، ﴿وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ﴾، وإلا فالنصر بيد الله، ليس بكثرة عدد ولا عُددٍ. السعدي:٣١٦.\nفعل الأسباب واجب، لكن من أين يأتي النصر الحقيقي؟\nوَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ١٠\nنبه على أن النصر من عنده -جل وعز- لا من الملائكة؛ أي: لولا نصره لمَا انتفع بكثرة العدد بالملائكة. القرطبي:٩/٤٥٨.\nأسباب النصر كثيرة، لكن من الناصر حقيقةً؟\nإِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ ١١\nوإنَّما كان (النعاس) أمنًا لهم؛ لأنهم لمَّا ناموا زال أثر الخوف من نفوسهم في مدة النوم، فتلك نعمة، ولما استيقظوا وجدوا نشاطًا، ونشاط الأعصاب يكسب صاحبه شجاعة، ويزيل شعور الخوف الذي هو فتور الأعصاب. ابن عاشور:٩/٢٧٨.\nكيف كان النعاس أمنة للمؤمنين؟\nوَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ\nأي: يُثَبِّتها؛ فإن ثبات القلب أصل ثبات البدن. السعدي:٣١٦.\nلماذا ذكر الله ثبات القلب قبل ثبات البدن؟\nإِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ\n﴿فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ﴾ أي: قووا قلوبهم. البغوي:٢/٢٠١.\nذكرت الآية عملًا من أعمال الملائكة؛ فما هو؟\nفَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ ١٢\nوإنَّما خصت الأعناق والبنان؛ لأن ضرب الأعناق إتلاف لأجساد المشركين، وضرب البنان يبطل صلاحية المضروب للقتال؛ لأن تناول السلاح إنَّما يكون بالأصابع. ابن عاشور:٩/٢٨٣.\nلماذا خصت الأعناق والبنان بالذكر في الآية الكريمة؟\nإِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ ١٢ ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ١٣\nفجعل إلقاء الرعب في قلوبهم و الأمر بقتلهم لأجل مشاقَّتهم لله ورسوله، فكل من شاقَّ الله ورسوله يستوجب ذلك. ابن تيمية:٣/٢٥٩.\nما عقوبات من شاقَّ الله ورسوله؟"],[179,"§الأنفال\nwords\nوَلِيُبلِيَ المُؤمِنِينَلِيُنعِمَ عَلَيهِم بِالنَّصرِ وَالأَجرِ.\nمُوهِنُمُضعِفُ.\nتَستَفتِحُواتَطلُبُوا -أَيُّهَا الكُفَّارُ- مِنَ اللهِ أَن يُوقِعَ بَأسَهُ بِالظَّالِمِينَ.\ndeeds\nانظر طاعة للرسول قصرت فيها، أو جهلتها، وبادر بالقيام بها.\nأكثر في السجود من قول: \"يا مقلب القلوب ثبت قلبي على دينك\"؛ كما كان -عليه الصلاة والسلام- يفعله؛ فإن الله يحول بين المرء وقلبه.\nأنكر منكرًا قدر استطاعتك، وإياك والسكوت؛ فيصيبك العذاب مع العاصين.\nguid\nإذا أصابتك مصيبةٌ بسبب ذنبٍ من ذنوبك فاعلم أن عودك للذنب يعني رجوع المصائب إليك مرة أخرى.\nاحذر من الإعراض عن الأوامر والنواهي؛ فقد يؤدي ذلك إلى شرور كثيرة أولها الختم على القلب.\nتأجيل التوبة قد يؤدي إلى الحرمان منها والعياذ بالله.\nrefl\nفَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ\nأي: ليس بحولكم وقوتكم قتلتم أعداءكم مع كثرة عددهم، وقلة عددكم؛ أي: بل هو الذي أظفركم عليهم. ابن كثير:٢/٢٨٣.\nإلى من ينسب قتل الكفار والظفر عليهم على وجه الحقيقة؟\nإِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ\nإن تستفتحوا فقد جاءكم الفتح؛ وذلك أن أبا جهل -لعنه الله- قال يوم بدر لمَّا التقى الناس: \"اللهم أينا أقطعنا للرحم، وأتانا بما لم نعرف؛ فأحِنْه الغداة\"؛ فكان هو المستفتح على نفسه. البغوي:٢/٢٠٦.\nلا يزال حلم الله على العبد حتى يجني العبد على نفسه، وضح ذلك من الآية.\nوَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ ١٩\nوهذه المعية -التي أخبر الله أنه يؤيد بها المؤمنين- تكون بحسب ما قاموا به من أعمال الإيمان؛ فإذا أُدِيل العدو على المؤمنين في بعض الأوقات فليس ذلك إلا تفريطًا من المؤمنين، وعدم قيام بواجب الإيمان ومقتضاه؛ وإلا فلو قاموا بما أمر الله به من كل وجه لما انهزم لهم راية انهزامًا مستقرًا، ولا أديل عليهم عدوهم أبدًا. السعدي:٣١٧-٣١٨.\nكيف نجمع بين معية الله للمؤمنين وغلبة الكفار عليهم أحيانًا؟\nإِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ ٢٢\nوالسمع الذي نفاه الله عنهم سمع المعنى المؤثر في القلب، وأمَّا سمع الحجة؛ فقد قامت حجة الله تعالى عليهم بما سمعوه من آياته، وإنَّما لم يسمعهم السمع النافع. السعدي:٣١٨.\nما السمع الذي نفاه الله عن المشركين؟ وماذا تفيد من ذلك؟\nوَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ٢٣\nودلت الآية على أنه ليس كل من سمع وفقه يكون فيه خير؛ بل قد يفقه ولا يعمل بعلمه، فلا ينتفع به، فلا يكون فيه خير، ودلت أيضًا على أن إسماع التفهيم إنَّما يطلب لمن فيه خير؛ فإنه هو الذي ينتفع به. ابن تيمية:٣/٢٦٥.\nهل كل من سمع وفقه يكون فيه خير؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ\nحياة القلب والروح بعبودية الله تعالى، ولزوم طاعته وطاعة رسوله على الدوام. السعدي:٣١٨.\nبِمَ تكون حياة القلب؟\nوَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ\nيحول بين الإنسان وقلبه، فلا يستطيع أن يؤمن ولا يكفر إلا بإذنه؛ عن أنس بن مالك -رضي الله عنه- قال: كان النبي -صلى الله عليه وسلم- يكثر أن يقول: «يا مقلب القلوب، ثبت قلبي على دينك». قال: فقلنا: يا رسول الله، آمنا بك وبما جئت به؛ فهل تخاف علينا؟ قال: «نعم، إن القلوب بين إصبعين من أصابع الله تعالى يقلبها». ابن كثير:٢/٢٨٥.\nإذا علمت أن قلبك بيد الله لا بيدك؛ فماذا يجب عليك؟"],[180,"§الأنفال\nwords\nيَتَخَطَّفَكُمُيَأخُذَكُمُ الكُفَّارُ بِسُرعَةٍ.\nفَآوَاكُمأَسكَنَكُمُ المَدِينَةَ.\nلِيُثبِتُوكَلِيَحبِسُوكَ.\nأَسَاطِيرُأَكَاذِيبُ، وَحِكَايَاتُ.\ndeeds\nكرر الأمر لأهلك وأولادك بالصلاة في وقتها؛ رجاء ألا تكون ممن فتنتهم أموالهم وأولادهم.\nألق كلمة، أو أرسل رسالة عن فوائد التقوى الدنيوية والأخروية بعد قراءة تفسير هذه الآية.\nأكثر من الاستغفار، واجعل لنفسك في ذلك وردًا معينًا، متذكرًا أن الاستغفار سبب لتفريج الكرب ورفع العذاب.\nguid\nالفرقان نور في القلب يفرق به المؤمن بين الأمور المتشابهات، ووسيلة الحصول عليه: تقوى الله تعالى، ومخالفة هوى النفس.\nقلة أهل الحق لا يلزم منها هزيمتهم.\nكثرة الاستغفار وانتشاره بين الناس سبب لدفع العذاب.\nrefl\nوَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ\nأي: اختبار وامتحان منه لكم؛ إذ أعطاكموها ليعلم أتشكرونه عليها، وتطيعونه فيها، أو تشتغلون بها عنه، وتعتاضون بها منه. ابن كثير:٢/٢٨٨.\nمتى تكون الأموال والأولاد نعمة، ومتى تكون نقمة؟\nوَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ٢٨\nفإن كان لكم عقلٌ ورأيٌ فآثِرُوا فضله العظيم على لذة صغيرة فانية مضمحلة؛ فالعاقل يوازن بين الأشياء، ويؤثر أَوْلاها بالإيثار، وأحقها بالتقديم. السعدي:٣١٩.\nهذه الآية أساسٌ في الموازنة بين زينة الدنيا ونعيم الآخرة، وضِّح ذلك من خلال الآية.\nوَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ٢٨\nهذا تنبيه على الحذر من الخيانة التي يحمل عليها المرء حب المال؛ وهي خيانة الغلول وغيرها؛ فتقديم الأموال لأنها مظنة الحمل على الخيانة في هذا المقام. ابن عاشور:٩/٣٢٤.\nلماذا قدمت الأموال على الأولاد في الآية الكريمة؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا\nفإن من اتقى الله بفعل أوامره، وترك زواجره وُفِّق لمعرفة الحق من الباطل. ابن كثير:٢/٢٨٩.\nالتفريق الدقيق بين الحق والباطل يحتاج إلى فرقان، فكيف نحصل عليه؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ٢٩\n﴿إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانًا﴾: مخرجًا في الدين من الشبهات، وقال عكرمة: \"نجاة\"؛ أي: يفرق بينكم وبين ما تخافون...وقال ابن إسحاق: \"فصلًا بين الحق والباطل\". البغوي:٢/٢١٤.\nما المقصود بالفرقان؟ وكيف يكتسبه الإنسان؟\nوَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ ٣٣\n﴿وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ﴾ أي: لو آمنوا واستغفروا؛ فإن الاستغفار أمان من العذاب، قال بعض السلف: \"كان لنا أمانان من العذاب: وهما وجود النبي والاستغفار، فلما مات النبي ذهب الأمان الواحد، وبقي الآخر\". ابن جزي:١/٣٤٣.\nفي ضوء هذه الآية: بيّن أهمية الاستغفار.\nوَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ ٣٣\nفأخبر أنه لا يعذب مستغفرا؛ لأن الاستغفار يمحو الذنب الذي هو سبب العذاب، فيندفع العذاب. ابن تيمية:٣/٢٦٨.\nلماذا لا يعذب الله تعالى المستغفرين؟"],[181,"§الأنفال\nwords\nمُكَاءًصَفِيرًا.\nوَتَصدِيَةًتَصفِيقًا.\nفَيَركُمَهُفَيَجعَلَهُ مُلقىً بَعضُهُ فَوقَ بَعضٍ.\nسُنَّةُ الأَوَّلِينَطَرِيقَتُنَا فِيهِم بِالهَلاَكِ إِذَا كَذَّبُوا.\ndeeds\nتبرع لإحدى الجمعيات الخيرية تقربًا إلى الله تعالى ومخالفة لصنيع المشركين.\nبادر اليوم بتوبة صادقة إلى ربك تعالى؛ فقد وعد الكفار -وهم أشد منك ذنبًا- بالتوبة والصفح إن انتهوا عن كفرهم.\nأرسل رسالة تبشر فيها المسرفين بالذنوب والكبائر أن الله وعد الكفار -وهم أشد منهم ذنبًا- بالعفو والصفح إن انتهوا عن كفرهم.\nguid\nلا يغرنَّك كثرة المشاريع و الأموال المرصودة للصد عن سبيل الله؛ فستكون حسرة ووبالًا عليهم في الدنيا والآخرة، وستفشل خططهم.\nأعظم فتنة هي وقوع الشرك واستقراره في البلد؛ ولذا أمر الله تعالى بدفع هذه الفتنة، ولو بالقتال.\nإذا عرفت أن الله مولاك؛ فلِمَ تخاف وتخشى؟!\nrefl\nوَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٣٤\nقال الحسن: كان المشركون يقولون: نحن أولياء المسجد الحرام، فرد الله عليهم بقوله: ﴿وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ﴾ أي: أولياء البيت، ﴿إِنۡ أَوۡلِيَآؤُهُۥٓ﴾ أي: ليس أولياء البيت ﴿إِلَّا ٱلۡمُتَّقُونَ﴾ يعني: المؤمنين الذين يتقون الشرك. البغوي:٢/٢١٩.\nبِمَ تكون ولاية البيت؟\nوَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ٣٥\nاتخاذ التصفيق والغناء والضرب بالدفوف والنفخ بالشبابات، والاجتماع على ذلك؛ دينًا وطريقًا إلى الله وقربة؛ فهذا ليس من دين الإسلام، وليس مما شرعه لهم نبيّهم محمد -صلى الله عليه وسلّم-، ولا أحد من خلفائه، ولا استحسن ذلك أحد من أئمة المسلمين؛ بل ولم يكن أحد من أهل الدين يفعل ذلك على عهد رسول الله -صلّى الله عليه وسلّم-، ولا عهد أصحابه، ولا تابعيهم بإحسان، ولا تابعي التابعين. القاسمي:٥/ ٢٨٩.\nلماذا كان اتخاذ التصفيق والغناء وضرب الدف دينًا بدعة من البدع؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ ٣٦\nأي: ليبطلوا الحق وينصروا الباطل، ويبطل توحيد الرحمن، ويقوم دين عبادة الأوثان. (فسينفقونها) أي: فسيصدرون هذه النفقة، وتخف عليهم لتمسكهم بالباطل، وشدة بغضهم للحق، ولكنها ستكون عليهم حسرة؛ أي: ندامةً وخزيًا وذلًا، ويغلبون؛ فتذهب أموالهم وما أملوا، ويعذبون في الآخرة أشد العذاب. السعدي:٣٢٠.\nخطط المنافقين والكفار في الباطل قوية، ونفقاتهم كثيرة؛ لكن ما مصيرها؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ ٣٦\nوأسندت الحسرة إلى الأموال لأنها سبب الحسرة بإنفاقها. ابن عاشور:٩/٣٤١.\nلماذا أسندت الحسرة إلى الأموال في الآية الكريمة؟\nقُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ ٣٨\nأي: إذا انتهوا عما نهوا عنه غفر لهم ما قد سلف. ابن تيمية:٣/٤٧٤.\nيحب الله توبة العبد، بين ذلك من الآية.\nوَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ\nفهذا المقصود من القتال والجهاد لأعداء الدين: أن يدفع شرهم عن الدين، وأن يذب عن دين الله الذي خلق الخلق له، حتى يكون هو العالي على سائر الأديان. السعدي:٣٢١.\nما النية الصحيحة والمقصود الأكبر للمجاهد في سبيل الله؟\nوَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ ٤٠\nومن كان الله مولاه وناصره فلا خوف عليه، ومن كان الله عليه فلا عِزَّ له ولا قائمة له. السعدي:٣٢١.\nما الذي يفيده المسلم من معرفة أن الله مولاه وناصره؟"],[182,"§الأنفال\nwords\nالجَمعَانِجَمعُ المُؤمِنِينَ، وَجَمعُ الكَافِرِينَ.\nبِالعُدوَةِ الدُّنيَابِجَانِبِ الوَادِي الأَقرَبِ إِلَى المَدِينَةِ.\nبِالعُدوَةِ القُصوَىبِجَانِبِ الوَادِي الأَبعَدِ.\nوَالرَّكبُعِيرُ قُرَيشٍ الَّتِي فِيهَا تِجَارَتُهُم.\nأَسفَلَ مِنكُمقَرِيبًا مِن سَاحِلِ البَحرِ الأَحمَرِ.\ndeeds\nتصدق اليوم على قريب، أو يتيم، أو مسكين، أو ابن سبيل.\nاستخرج ثلاث فوائد من غزوة بدر بعد التأمل في أحداثها.\nأَرسل رسالة تبين فيها أن من محبة الله لذِكره أنه أمر به في أشد حالات انشغال الإنسان.\nguid\nإذا رأيت رؤيا فلا تفسرها إلا عند من يجيد تعبير الرؤى، وغلِّب جانب التفاؤل دائمًا.\nإذا أراد الله أمرًا هيّأ له أسبابه.\nذكر الله يقوي المجاهدين حال مقارعتهم لأعدائهم بالسيوف، أفلا يقويك على تيسير حاجاتك وحل مشكلاتك؟! فلا تغفل عنه.\nrefl\nوَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ\nفالإضافة للرسول لأنه هو الذي يقسم هذه الأموال بأمر الله، ليست ملكًا لأحد، وقوله -صلى الله عليه وسلم-: «إني والله لا أعطي أحدًا، ولا أمنع أحدًا، وإنَّما أنا قاسم؛ أضع حيث أمرت» يدل على أنه ليس بمالك للأموال، وإنَّما هو منفذ لأمر الله -عز وجل- فيها، ابن تيمية ٣/٢٧٨.\nما معنى إضافة الأموال للرسول -صلى الله عليه وسلم-؟\nوَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ\nأي: اليوم الذي فرقت فيه بين الحق والباطل؛ وهو يوم بدر. القرطبي: ١٠/٣٥.\nلماذا سمى الله تعالى يوم بدر: \"يوم الفرقان\"؟\nإِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ\nوقد أريد من هذا الظرف وما أشيف إليه تذكيرهم بحالة حرجة كان المسلمون فيها، وتنبيههم للطف عظيم حفَّهم من الله تعالى؛ وهي حالة موقع جيش المسلمين من جيش المشركين، وكيف التقى الجيشان في مكان واحد عن غير ميعاد، ووجد المسلمون أنفسهم أمام عدو قوي العدد والعدة والمكانة من حسن الموقع؛ ولولا هذا المقصد من وصف هذه الهيئة لما كان من داع لهذا الإطناب؛ إذ ليس من أغراض القرآن وصف المنازل إذا لم تكن في عبرة. ابن عاشور: ١٠/١٥-١٦.\nما المقصد من وصف الأماكن التي كان فيها المسلمون والكفار في غزوة بدر؟\nوَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ\n﴿وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ﴾ أي: لو تواعدتم مع قريش، ثم علمتم كثرتهم وقلتكم لاختلفتم ولم تجتمعوا معهم، أو: لو تواعدتم لم يتفق اجتماعكم مثل ما اتفق بتيسير الله ولطفه. ﴿لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٍ﴾ أي: يموت من مات ببدر عن إعذار وإقامة الحجة عليه، ويعيش من عاش بعد البيان له. ابن جزي: ١/٣٥٤.\nإذا أراد الله أمرًا هيَّأ له أسبابه، وضح ذلك من الآية.\nإِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ\nوكان الله قد أرى رسوله المشركين في الرؤيا عددًا قليلًا، فبشر بذلك أصحابه؛ فاطمأنت قلوبهم، وتثبتت أفئدتهم، ولو أراكهم الله إياهم كثيرًا فأخبرت بذلك أصحابك؛ ﴿لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ﴾: فمنكم من يرى الإقدام على قتالهم، ومنكم من لا يرى ذلك؛ فوقع من الاختلاف والتنازع ما يوجب الفشل. السعدي: ٣٢٢.\nكيف كانت الرؤيا التي رآها النبي -صلى الله عليه وسلم- في منامه مثبتة لأصحابه؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ٤٥\nفالصبر والثبات والإكثار من ذكر الله من أكبر الأسباب للنصر. السعدي: ٣٢٢.\nتضمن الآية أكبر أسباب النصر، فاذكرها.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا\nعن قتادة في هذه الآية: \"افترض الله ذكره عند أشغل ما يكون؛ عند الضرب بالسيوف\". ابن كثير ٢/٣٠٢.\nكيف تستدل بهذه الآية على أهمية ذكر الله -سبحانه وتعالى-؟"],[183,"§الأنفال\nwords\nبَطَرًاكِبرًا.\nجَارٌ لَكُمنَاصِرُكُم، وَمُجِيرُكُم.\nتَرَاءَتِتَقَابَلَت.\nنَكَصَرَجَعَ مُدبِرًا.\nكَدَأبِكَعَادَةِ، وَسُنَّةِ.\ndeeds\nحذر من حولك بكلمة أو رسالة توجيهية من النزاع؛ فإن النزاع بداية الفشل.\nأصلح بين اثنين من المتخاصمين حولك.\nاشتملت الآية على مرضين قاتلين من أمراض القلوب، استخرجهما، واستعذ بالله منهما.\nguid\nاحرص على جمع القلوب على شريعة الإسلام؛ وخاصةً في أوقات الشدائد والملمات.\nاعرض أفكارك دائمًا على الكتاب والسنة، ولاتتردد في رد ما خالفهما حتى لا يزينه الشيطان لك.\nكل شيطان من الإنس والجن سيتخلى عن من أغواه ويتبرأ منه إذا وقع في العذاب؛ فإياك والاستسلام لهم.\nrefl\nوَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ٤٦\nالنهي عن التنازع... يقتضي الأمر بتحصيل أسباب ذلك: بالتفاهم، والتشاور، ومراجعة بعضهم بعضًا؛ حتى يصدروا عن رأي واحد، فإن تنازعوا في شيء رجعوا إلى أمرائهم؛ لقوله تعالى: ﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ﴾ [النساء:٨٣]، وقوله: ﴿فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ﴾ [النساء: ٥٩]. والنهي عن التنازع أعم من الأمر بالطاعة لولاة الأمور؛ لأنهم إذا نهوا عن التنازع بينهم فالتنازع مع ولي الأمر أولى بالنهي. ابن عاشور:١٠/٣٠.\nاذكر بعض الأسباب التي تمنع التنازع.\nوَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ٤٦\nوإنَّما كان التنازع مفضيًا إلى الفشل؛ لأنه يثير التغاضب، ويزيل التعاون بين القوم، ويحدث فيهم أن يتربص بعضهم ببعض الدوائر؛ فيحدث في نفوسهم الاشتغال باتقاء بعضهم بعضًا، وتوقع عدم إلفاء النصير عند مآزق القتال؛ فيصرف الأمة عن التوجه إلى شغل واحد فيما فيه نفع جميعهم، ويصرف الجيش عن الإقدام على أعدائهم؛ فيتمكن منهم العدو. ابن عاشور:١٠/٣١.\nبيّن ثلاثة من أضرار التنازع.\nوَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ\nفليكن قصدكم في خروجكم: وجه الله تعالى، وإعلاء دين الله، والصد عن الطرق الموصلة إلى سخط الله وعقابه، وجذب الناس إلى سبيل الله القويم الموصل لجنات النعيم. السعدي:٣٢٣.\nبَيَّن الفرق بين الخروج في سبيل الله والخروج للصد عن سبيل الله.\nوَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ ٤٧\nوالبطر في اللغة: التقوية بنعم الله -عز وجل- وما ألبسه من العافية على المعاصي. القرطبي:١٠/٤٢.\nما البطر الذي نهانا عنه ربنا -سبحانه وتعالى-؟\nإِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ ٤٨\nفأخبر عن الشيطان أنه يخاف الله. والعقوبة إنَّما تكون على ترك مأمور، أو فعل محظور. ابن تيمية:٣/٢١٨.\nالخوف من الله تعالى لا يكفي في دفع العذاب؛ حتى يكون مع الخوف فعل المأمور وترك المحظور، بين ذلك.\nوَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ٤٩\n﴿وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ﴾ أي: ومن يسلم أمره إلى الله ويثق به؛ ﴿فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ﴾: قوي، يفعل بأعدائه ما يشاء. البغوي:٢/٢٣١.\nبيِّن العاقبة الحسنة لمن توكل على الله تعالى وفوض أمره إليه.\nوَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ٥٠\nهذا عند الموت: تضرب الملائكة وجوه الكفار وأدبارهم بسياط النار. البغوي:٢/٢٣١.\nكيف يكون عذاب الكفار عند الموت؟"],[184,"§الأنفال\nwords\nتَثقَفَنَّهُمتَجِدَنَّهُم.\nفَانبِذفاطرَح عَهدَهُم.\nعَلَى سَوَاءٍلِتَكُونُوا وَإِيَّاهُم مُستَوِينَ فِي العِلمِ بِطَرحِهِ.\nجَنَحُوامَالُوا.\nفَاجنَحمِل.\ndeeds\nابحث عن معصية في نفسك قد تكون غافلًا عنها، وتب إلى الله منها؛ لعل الله أن يغير حالك إلى الأفضل.\nتأمل قصة فرعون، وما آل إليه، ثم استخرج ثلاثًا من فوائدها.\nابحث في نفسك عن موهبة أنعم الله بها عليك، ثم استخدمها في طاعة الله وخدمة دينه.\nguid\nأساس الحياة السعيدة التوبة وكثرة العبادة.\nإذا وعدت فإياك أن تخلف أو تنقض العهد، ولو كان ذلك مع الكفار؛ فليس ذاك من صفات المؤمنين.\nإرهاب أعداء الإسلام المحاربين أمر مقصود شرعًا؛ خلافًا لما يصوره الإعلام -سواء كان إرهاب حجة وبيان، أو قوة عتاد وأبدان-، كما يرهبوننا هم بذلك.\nrefl\nذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ\nأراد أن الله تعالى لا يغير ما أنعم على قوم حتى يغيروا هم ما بهم بالكفران وترك الشكر؛ فإذا فعلوا ذلك غيَّر الله ما بهم، فسلبهم النعمة. البغوي:٢/٢٣٢.\nمتى يغير الله تعالى حال المجتمع؟\nذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ\n(ذلك) العذاب الذي أوقعه الله بالأمم المكذبين، وأزال عنهم ما هم فيه من النعم والنعيم بسبب ذنوبهم وتغييرهم ما بأنفسهم؛ فإن الله لم يك مغيرًا نعمة أنعمها على قوم من نعم الدين والدنيا، بل يبقيها، ويزيدهم منها إن ازدادوا له شكرًا، ﴿حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ﴾ من الطاعة إلى المعصية؛ فيكفروا نعمة الله، ويبدلوها كفرا؛ فيسلبهم إياها، ويغيرها عليهم كما غيروا ما بأنفسهم، ولله الحكمة في ذلك، والعدل والإحسان إلى عباده؛ حيث لم يعاقبهم إلا بظلمهم. السعدي:٣٢٤.\nمن غَيَّر ما بنفسه زالت نعمته، فما حال من ثبت على ما في نفسه؟\nذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ\nوهذا التغيير نوعان؛ أحدهما: أن يُبدوا ذلك فيبقى قولًا وعملًا يترتب عليه الذم والعقاب. والثاني: أن يغيِّروا الإيمان الذي في قلوبهم بضده من الريب والشك والبغض، ويعزموا على ترك فعل ما أمر الله به ورسوله. ابن تيمية:٣/٢٨٢.\nتغيير ما في الأنفس نوعان: ظاهر وباطن؛ بين ذلك.\nٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ ٥٦\nوالتعبير -في جانب نقضهم العهد- بصيغة المضارع للدلالة على أن ذلك يتجدد منهم ويتكرر بعد نزول هذه الآية، وأنهم لا ينتهون عنه؛ فهو تعريض بالتأييس من وفائهم بعهدهم. ابن عاشور:١٠/ ٤٨.\nما فائدة التعبير في جانب نقض المشركين للعهد بصيغة المضارع (ينقضون)؟\nفَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ ٥٧\nوهذه من فوائد العقوبات والحدود المرتبة على المعاصي: أنها سبب لازدجار من لم يعمل المعاصي، بل وزجرًا لمن عملها أن لا يعاودها. السعدي:٣٢٤.\nما فوائد عقوبة العصاة؟\nوَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ ٥٨\nوإنَّما رتب نبذ العهد على خوف الخيانة، دون وقوعها؛ لأن شؤون المعاملات السياسية والحربية تجري على حسب الظنون ومخائل الأحوال، ولا ينتظر تحقق وقوع الأمر المظنون؛ لأنه إذا تريث ولاة الأمور في ذلك يكونون قد عرضوا الأمة للخطر، أو للتورط في غفلة وضياع مصلحة. ابن عاشور:١٠/٥٢.\nلماذا رتبت الآية الكريمة نبذ العهد على خوف الخيانة وليس على وقوعها؟\nوَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا\nفإن في ذلك فوائد كثيرة؛ منها: أن طلب العافية مطلوب كل وقت، فإذا كانوا هم المبتدئين في ذلك كان أولى لإجابتهم، ومنها: أن في ذلك إجمامًا لقواكم، واستعدادًا منكم لقتالهم في وقت آخر إن احتيج لذلك، ومنها: أنكم إذا اصطلحتم وأَمِنَ بعضُكم بعضًا، وتمكن كلٌ من معرفة ما عليه الآخر؛ فإن الإسلام يعلو ولا يُعلى عليه، فكل من له عقل وبصيرة إذا كان معه إنصاف فلا بد أن يؤثره على غيره من الأديان. السعدي:٣٢٥.\nما فوائد السلم على المسلمين إذا طلبه الكفار، وتوفرت شروطه؟"],[185,"§الأنفال\nwords\nحَسبَكَكَافِيَكَ.\nحَرِّضِحُثَّ.\nيُثخِنَيُبَالِغَ فِي القَتلِ.\ndeeds\nادع الله تعالى بإلحاح أن يؤلّف بين قلوب إخوانك من المسلمين.\nأكثر من قول: \"لا حول ولا قوة إلا بالله\"، وقول: \"حسبي الله لا إله إلا هو عليه توكلت وهو رب العرش العظيم\".\nاقرأ سبب نزول هذه الآية، ثم ألقه على زملائك، واستخرجوا ما فيه من فوائد، أو أرسله برسالة.\nguid\nالأخوة إذا كانت إيمانية حقيقة فإنها تذهب ما في القلوب من الضغينة والشحناء.\nمعية الله بالعلم والتأييد والنصر هي للصابرين المؤمنين دون أهل الجزع والمشككين.\nمهما كان العبد فإنه يحتاج إلى رحمة الله تعالى؛ لأنه ضعيف لا يملك من أمره شيئًا.\nrefl\nوَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ\nقال ابن عباس: \"... إن الله إذا قارب بين القلوب لم يزحزحها شيء\"، ثم قرأ هذه الآية. ابن كثير:٢/٣٠٩.\nإذا أردت أن تؤلف بين قلوب إخوانك؛ فما أهم أمر تبدأ به؟\nوَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ ٦٣\nأي: جمع بين قلوب الأوس والخزرج، وكان تألُّف القلوب مع العصبية الشديدة في العرب من آيات النبي -صلى الله عليه وسلم- ومعجزاته؛ لأن أحدهم كان يُلطم اللطمة؛ فيقاتل عنها حتى يستقيدها، وكانوا أشدّ خلق الله حميَّة. فألف الله بالإيمان بينهم؛ حتى قاتل الرجل أباه وأخاه بسبب الدين. القرطبي:١٠/٦٧.\nالإيمان الصادق له علامات على الجماعة، بيِّنها.\nيَٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ٦٤\nوهذا وعد من الله لعباده المؤمنين المتبعين لرسوله بالكفاية والنصرة على الأعداء؛ فإذا أتوا بالسبب الذي هو الإيمان والاتباع فلا بُدَّ أن يكفيَهم ما أهمهم من أمور الدين والدنيا، وإنَّما تتخلف الكفاية بتخلُّف شرطها. السعدي:٣٢٥.\nما شروط كفاية الله ونصرته لأوليائه؟\nإِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ٦٥\n﴿بِأَنَّهُمۡ قَوۡمٌ لَّا يَفۡقَهُونَ﴾ أي: يقاتلون على غير دين ولا بصيرة فلا يثبتون. ابن جزي:١/ ٣٤٨.\nذكرت هذه الآية شرطًا محكمًا للغلبة لا يتخلّف فما هو؟\nإِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ٦٥\n﴿قَوۡمٌ لَّا يَفۡقَهُونَ﴾ أي: لا عِلمَ عندهم بما أعد الله للمجاهدين في سبيله؛ فهم يُقَاتِلُون لأجل العلو في الأرض والفساد فيها، وأنتم تفقهون المقصود من القتال: أنه لإعلاء كلمة الله، وإظهار دينه، والذب عن كتاب الله، وحصول الفوز الأكبر عند الله؛ وهذه كلها دواعٍ للشجاعة والصبر والإقدام على القتال. السعدي:٣٢٦.\nما قيمةُ فقه معاني الجهاد في الانتصار على الأعداء؟\nتُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ٦٧\n(تريدون) أيها المؤمنون ﴿عَرَضَ ٱلدُّنۡيَا﴾ بأخذكم الفداء، ﴿وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ﴾: يريد لكم ثواب الآخرة بقهركم المشركين، ونصركم دين الله -عز وجل-، والله عزيز حكيم. البغوي:٢/٢٣٩.\nعند القتال تظهر نيات كثيرة، فما النية التي يحبها الله -عز وجل-؟\nتُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ٦٧\n﴿عَرَضَ ٱلدُّنۡيَا﴾: هو المال؛ وإنَّما سمي عرضًا لأن الانتفاع به قليل اللبث، فأشبه الشيء العارض؛ إذ العُروض مرور الشيء وعدم مكثه؛ لأنه يعرض للماشين بدون تهيؤ. ابن عاشور:١٠/٧٦.\nما ﴿عَرَضَ ٱلدُّنۡيَا﴾؟ ولماذا سمي بهذا الاسم؟"],[186,"§الأنفال\nwords\nفَأَمكَنَ مِنهُمأَقدَرَكَ عَلَيهِم.\nآوَواأَنزَلُوا المُهَاجِرِينَ فِي دُورِهِم.\nوَأُولُوالأَرحَامِ ذَوُوا القَرَابَاتِ.\ndeeds\nتبرع بشيء من مالك للجهات الخيرية رجاء أن تلحق بالمجاهدين بأموالهم.\nواسِ أحد المغتربين ممن هم في بلدك، وآوه، وآنسه من وحشته؛ فإن الله تعالى أثنى على الأنصار بإيوائهم لإخوانهم المهاجرين.\nاعمل شيئًا تصل به رحمك من: تعليمهم العلم، أو إطعامهم، أو قضاء حاجتهم؛ فهم أولى بك من غيرهم.\nguid\nالله -جل جلاله- لا يغلبه غالب، ولا يفوته هارب.\nحق على كل مسلم مناصرة إخوانه المسلمين؛ إن استنصروه في الدين.\nاحذر من ولاية الكفار؛ فإنها فتنة وفساد كبير.\nrefl\nوَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۢ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ\nابن العربي: \"إلا أن يكونوا أُسراء مستضعفين؛ فإن الولاية معهم قائمة، والنصرة لهم واجبة حتى لا تبقى منَّا عين تطرف، حتى نخرج إلى استنقاذهم إن كان عددنا يحتمل ذلك، أو نبذل جميع أموالنا في استخراجهم حتى لا يبقى لأحد درهم؛ كذلك قال مالك وجميع العلماء؛ فإنا لله وإنا إليه راجعون على ما حل بالخلق في ترك إخوانهم في أسر العدو، وبأيديهم خزائن الأموال، وفضول الأحوال، والقدرة والعدد، والقوة والجلد. القرطبي:١٠/٣٤٧.\nبيّن واجبنا الشرعي تجاه أسارى المسلمين المستضعفين.\nوَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۢ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ٧٢\nوقوله: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ﴾ تحذير للمسلمين؛ لئلَّا يحملهم العطف على المسلمين على أن يقاتلوا قومًا بينهم وبينهم ميثاق. وفي هذا التحذير تنويه بشأن الوفاء بالعهد، وأنه لا ينقضه إلا أمر صريح في مخالفته. ابن عاشور:١٠/٨٧.\nما فائدة ختم الآية الكريمة بقوله تعالى: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ﴾؟\nوَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ ٧٣\nقطع الله الولاية بين الكفار والمؤمنين، فجعل المؤمنين بعضهم أولياء بعض، والكفار بعضهم أولياء بعض. القرطبي:١٠/٨٧.\nما خطورة زوال الولاء والبراء من حياة المسلمين؟\nوَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ ٧٣\nيعني أن في كل من الكفار قوة الموالاة للآخر عليكم والميل العظيم الحاثّ لهم على المسارعة في ذلك وإن اشتدت عداوة بعضهم لبعض؛ لأنكم حزب وهم حزب، يجمعهم داعي الشيطان بوصف الكفران كما يجمعكم داعي الرحمن بوصف الإيمان. البقاعي:٣/٢٥٢.\nعلى أي شيء يتفق الكفار ويوالي بعضهم بعضًا، رغم اختلاف أنواعهم؟\nوَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ ٧٣\n﴿إِلَّا تَفۡعَلُوهُ﴾ أي: موالاة المؤمنين ومعاداة الكافرين... ﴿تَكُن فِتۡنَةٌ فِي ٱلۡأَرۡضِ وَفَسَادٌ كَبِيرٌ﴾: فإنه يحصل بذلك من الشر ما لا ينحصر من اختلاط الحق بالباطل، والمؤمن بالكافر، وعدم كثير من العبادات الكبار؛ كالجهاد والهجرة، وغير ذلك من مقاصد الشرع والدين التي تفوت إذا لم يُتخذ المؤمنون وحدهم أولياء بعضهم لبعض. السعدي:٣٢٨.\nمثل لبعض أنواع الفتنة الحاصلة بعدم معاداة الكافرين.\nوَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ\nهم المؤمنون حقًا؛ لأنهم صدَّقوا إيمانهم بما قاموا به من الهجرة، والنصرة، والموالاة بعضهم لبعض، وجهادهم لأعدائهم من الكفار والمنافقين. السعدي:٣٢٨.\nما صفات المؤمنين حقًا؟\nوَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ\nفهذه الموالاة الإيمانية لها وقع كبير وشأن عظيم، حتى إن النبي -صلى الله عليه وسلم- آخى بين المهاجرين والأنصار أخوة خاصة غير الأخوة الإيمانية العامة، وحتى كانوا يتوارثون بها؛ فأنزل الله: ﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٍ فِي كِتَٰبِ ٱللَّهِۚ﴾: فلا يرثه إلا أقاربه. السعدي:٣٢٨.\nاذكر صورةً كانت في أول الإسلام تدل على أهمية الموالاة بين المؤمنين؟"],[187,"§التوبة\nwords\nوَأَذَانٌإِعلاَمٌ.\nلَم يَنقُصُوكُملَم يَخُونُوا العَهدَ.\nانسَلَخَانقَضَى.\nوَاحصُرُوهُمحَاصِرُوهُم فِي مَعَاقِلِهِم.\nاستَجَارَكَطَلَبَ الأَمَانَ مِنَ القَتلِ.\ndeeds\nابحث عن أسماء سورة التوبة، وسبب تسميتها بهذه الأسماء، ثم استخرج ثلاث فوائد من ذلك.\nحافظ على الصلاة، وتصدق بشيء من مالك، لعلها تغفر ذنوبك.\nاقرأ كلام الله تعالى على من حولك من غير المسلمين رجاء هدايتهم.\nguid\nلقد برئ الله ورسوله من المشركين، فما موقفك منهم؟!\nتأمل كيف يدعو الله تعالى أعداء الإسلام إلى التوبة والإقبال عليه، ويعدهم بالخير؛ فكيف بأهل الإيمان؟!\nمن أكثر الأمور التي تنفع في الدعوة الإسلامية: إسماع الكفار آيات القرآن الكريم، أو ترجمتها.\nrefl\nبَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ١\nقال علي بن أبي طالب: \"البسملة أمان، وبراءة نزلت بالسيف؛ فلذلك لم تبدأ بالأمان\". ابن جزي:١/٣٥٠.\nفي عدم نزول البسملة في سورة التوبة دليل على قوة القرآن مع المعاندين من الكفار، وضح ذلك.\nبَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ١\nوأما قوله سبحانه: ﴿بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ﴾ فتلك عهود جائزة لا لازمة؛ فإنها كانت مطلقة، وكان مخيرًا بين إمضائها ونقضها. ابن تيمية:٣/٣٠٠.\nهل كانت العهود التي مع المشركين جائزة أو لازمة؟\nوَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ\nوهذا أمر للمسلمين بأن يأذنوا المشركين بهذه البراءة؛ لئلَّا يكونوا غادرين. ابن عاشور:١٠/١٠٨.\nلماذا أمر المسلمون بإخبار المشركين بإنهاء العهد بينهم؟\nفَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ٥\nهذه الآية دالة على أن من قال: قد تبت؛ أنه لا يُجتزأ بقوله حتى ينضاف إلى ذلك أفعاله المحققة للتوبة؛ لأن الله -عز وجل- شرط هنا مع التوبة إقام الصلاة، وإيتاء الزكاة؛ ليتحقق بهما التوبة. القرطبي:١٠/١١٤.\nما تقول فيمن يتوب بلسانه فحسب، ويكتفي بذلك تاركًا العمل؟\nفَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ\nونبه بأعلاها على أدناها؛ فإن أشرف أركان الإسلام بعد الشهادتين الصلاة التي هي حق الله -عز وجل-، وبعدها أداء الزكاة التي هي نفع متعدٍ إلى الفقراء والمحاويج، وهي أشرف الأفعال المتعلقة بالمخلوقين، ولهذا كثيرًا ما يقرن الله بين الصلاة والزكاة. ابن كثير:٢/٣٢١.\nلماذا ذُكِرَت الصلاة والزكاة دون سائر العبادات؟\nوَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ ٦\nأي: سأل جوارك؛ أي: أمانك وذمامك، فأعطه إياه ليسمع القرآن، أي: يفهم أحكامه وأوامره ونواهيه؛ فإن قَبِل أمرًا فحسن، وإن أبى فرده إلى مأمنه. القرطبي:١٠/١١٤.\nبيّن السبب في إعطاء الشرع الأمان للكافر.\nوَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ\n﴿حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ﴾ أي: القرآن؛ تقرأه عليه، وتذكر له شيئًا من أمر الدين، تقيم به عليه حجة الله... وكان ذلك وأمثاله من أكبر أسباب هداية أكثرهم. ابن كثير:٢/٣٢٢.\nما الحكمة من إسماع المشركين القرآن؟"],[188,"§التوبة\nwords\nاستَقَامُواوَفَوا بِعَهدِكُم.\nوَإِن يَظهَرُوايَظفَرُوا بِكُم.\nنَكَثُوانَقَضُوا.\nأَيمَانَهُممَوَاثِيقَهُم، وَعُهُودَهُم.\nلاَ أَيمَانَلاَ عَهدَ لَهُم وَلاَ ذِمَّةَ.\ndeeds\nابحث عن فعل تحبه نفسك ويبغضه الله، واتركه تقوى لله -عز وجل-.\nحافظ على الصلوات في أوقاتها مع الجماعة.\nقل: \"اللهم إني أسألك خشيتك في الغيب والشهادة، وكلمة الحق في الرضى والغضب\".\nguid\nلا تَأمَن غير المسلمين، ولا تسَلِّم لهم نفسك ورقبتك مهما كانت وعودهم؛ فإنهم لا يؤمَنون.\nأخوة الإسلام تثبت بثلاثة أمور: التوحيد، وإقام الصلاة، وإيتاء الزكاة.\nالطعن في الدين ردة وكفر موجب للقتل والقتال.\nrefl\nٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ٩\nاستبدلوا بذلك ﴿ثَمَنًا قَلِيلًا﴾، أي: شيئًا حقيرًا من حطام الدنيا؛ وهو أهواؤهم وشهواتهم التي اتبعوها. والجملة... مستأنفة كالتعليل لقوله تعالى: ﴿وَأَكۡثَرُهُمۡ فَٰسِقُونَ﴾؛ فيه أن من فسق وتمرد كان سببه مجرد اتباع الشهوات، والركون إلى اللذات. الألوسي:٥/٢٥١.\nبيِّن خطورة اتباع الشهوات، وأثره على دين المسلم من خلال الآية.\nلَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ\nفالوصف الذي جعلهم يعادونكم لأجله ويبغضونكم هو الإيمان؛ فذُبوا عن دينكم، وانصروه، واتخذوا من عاداه لكم عدوًا، ومن نصره لكم وليًا، واجعلوا الحكم يدور معه وجودًا وعدمًا، لا تجعلوا الولاية والعداوة طبيعية؛ تميلون بهما حيثما مال الهوى، وتتبعون فيهما النفس الأمارة بالسوء. السعدي:٣٣٠.\nما الحكمة في اختيار اسم الإيمان في هذا الموضع: ﴿فِي مُؤۡمِنٍ﴾؟ وما الذي يفيده المسلم من هذا؟\nفَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ\nفعلّق الأُخوَّةَ في الدين على التوبة من الشرك، وإقام الصلاة، وإيتاء الزكاة؛ والمعلق بالشرط ينعدم عند عدمه؛ فمن لم يفعل ذلك فليس بأخ في الدين. ابن تيمية:٣/٣١١.\nهل تارك الصلاة أخ في الدين؟\nفَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ\n﴿فَإِن تَابُواْ﴾: من الشرك، (وأقاموا الصلاة وآتوا الزكاة فإخوانكم) أي: فهم إخوانكم ﴿فِي ٱلدِّينِۖ﴾: لهم ما لكم، وعليهم ما عليكم. البغوي:٢/٢٥٣\nما الأسس التي تتحقق بها الأخوة بين المؤمنين؟\nوَطَعَنُواْ فِي دِينِكُمۡ\nوالطعن: هو أن ينسب إليه ما لا يليق به، أو يعترض بالاستخفاف على ما هو من الدين لما ثبت من الدليل القطعي على صحة أصوله، واستقامة فروعه. القرطبي:١٠/١٢٣.\nكيف يكون الطعن في الدين؟\nفَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ\nوخصهم بالذكر لعِظَم جنايتهم، ولأن غيرهم تبع لهم، وليدل على أن من طعن في الدين وتصدى للرد عليه فإنه من أئمة الكفر. السعدي:٣٣٠.\nلماذا خَصَّ أئمة الكفر بالقتال؟\nأَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ ١٣\nوجيء بالشرط المتعلق بالمستقبل -مع أنه لا شك فيه- لقصد إثارة همتهم الدينية؛ فيبرهنوا على أنهم مؤمنون حقًّا، يقدمون خشية الله على خشية الناس. ابن عاشور:١٠/١٣٤.\nلماذا جيء بالشرط ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾ في الآية الكريمة؟"],[189,"§التوبة\nwords\nوَلِيجَةًبِطَانَةً، وَأَولِيَاءَ.\ndeeds\nاكتب مقالًا أو رسالةً تفضح أساليب المنافقين في إفساد المجتمع أو محاربتهم للدين.\nامكث في المسجد لذكر الله قبل الصلاة أو بعدها، أو بين المغرب والعشاء؛ فهذا من عمارة المسجد.\nسل الله تعالى أن يرزقك الخشية؛ فإنها أجلُّ علامات الهداية.\nguid\nلا بُدَّ أن تمر عليك ابتلاءات وامتحانات من الله تبين هل أنت صادق في إيمانك.\nاحذر اتخاذ بطانة من أعداء الدين.\nالأعمال الصالحة لا تنفع مع عدم وجود التوحيد الخالص.\nrefl\nقَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ ١٤\nقال تعالى عزيمة على المؤمنين، وبيانًا لحكمته فيما شرع لهم من الجهاد مع قدرته على إهلاك الأعداء بأمر من عنده: ﴿قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٍ مُّؤۡمِنِينَ﴾. ابن كثير:٢/٣٢٥.\nلِمَ شرع الجهاد والله قادر على إهلاك الأعداء بأمر من عنده؟\nوَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ ١٤ وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ\nوهذا يدل على محبة الله لعباده المؤمنين، واعتنائه بأحوالهم؛ حتى أنه جعل من جملة المقاصد الشرعية شفاء ما في صدورهم وذهاب غيظهم. السعدي:٣٣١.\nدلت الآية على محبة الله لعباده المؤمنين، وضح ذلك.\nوَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ١٥\nوالتذييل بجملة: ﴿وَٱللَّهُ عَلِيمٌ حَكِيمٌ﴾ لإفادة أن الله يعامل الناس بما يعلم من نياتهم، وأنه حكيم لا يأمر إلا بما فيه تحقيق الحكمة؛ فوجب على الناس امتثال أوامره. ابن عاشور:١٠/١٣٧.\nما فائدة تذييل الآية الكريمة بــ﴿وَٱللَّهُ عَلِيمٌ حَكِيمٌ﴾؟\nإِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ ١٨\nفبين أن عُمَّار المساجد هم الذين لا يخشون إلا الله، ومن لم يخش إلا الله فلا يرجو ويتوكل إلا عليه؛ فإن الرجاء والخوف متلازمان. والذين يحجون إلى القبور يدعون أهلها، ويتضرعون لهم، ويعبدونهم، ويخشون غير الله، ويرجون غير الله؛ كالمشركين الذين يخشون آلهتهم ويرجونها. ابن تيمية:٣/٣٢٧.\nما الفرق بين عُمَّار المساجد وعُمَّار المشاهد؟\nإِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ ١٨\nوأَمَّا من لم يؤمن بالله ولا باليوم والآخر، ولا عنده خشية لله؛ فهذا ليس من عمار مساجد الله، ولا من أهلها الذين هم أهلها، وإن زعم ذلك وادَّعَاه. السعدي:٣٣١.\nما علامة عمارة المسجد المقبولة عند الله سبحانه؟\nأَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٩\nيعني: الذين زعموا أنهم أهل العمارة، فسماهم الله ظالمين بشركهم، فلم تغن عنهم العمارة شيئًا. ابن كثير ٢/٣٢٧.\nمن لم يوحد الله -سبحانه وتعالى- هل يكون عمله الصالح نافعًا له في شيء؟\nأَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٩\nسببها أن قومًا من قريش افتخروا بسقاية الحاج، وبعمارة المسجد الحرام؛ فبين الله أن الجهاد أفضل من ذلك. ابن جزي:١/٣٥٣.\nكيف تستدل بهذه الآية على تفاضل الأعمال؟"],[190,"§التوبة\nwords\nاقتَرَفتُمُوهَااكتَسَبتُمُوهَا.\nكَسَادَهَاعَدَمَ رَوَاجِهَا.\nفَلَم تُغنِعَنكُم لَم تَنفَعكُم.\ndeeds\nابحث عن صديق إذا جالسته زاد إيمانك، واتخذه صاحبًا.\nحدد شيئًا شغلك عن محبة الله، ثم اسعَ في تخفيف محبتك له.\nقل: \"اللهم اجعل ما رزقتني من نعم ظاهرة وباطنة سببًا لرضاك والقرب منك، ولا تشغلني بها عن محبتك\".\nguid\nالولاية الدينية أعظم وأشرف من ولاية النسب.\nالنصر إنَّما يكون من عند الله تعالى وحده؛ فهو ليس بعدد ولا عتاد ولا قوة.\nإيمان المجاهدين وصدق توكلهم على الله تعالى أهم من كثرة عددهم وعتادهم.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ\n﴿لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ﴾ الذين هم أقرب الناس إليكم، وغيرهم من باب أولى وأحرى، فلا تتخذوهم ﴿أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ﴾ أي: اختاروا على وجه الرضا والمحبة ﴿ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ﴾. السعدي:٣٣٢.\nلماذا خَصَّ الله الآباء والإخوان بالذكر؟\nقُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ٢٤\nوعيد لمن آثر أهله، أو ماله، أو مسكنه على الهجرة والجهاد. ابن جزي:١/٣٥٤.\nما خطورة المبالغة في محبة الأهل، والمال، والمسكن؟\nقُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ٢٤\nهذه الآية الكريمة أعظم دليل على وجوب محبة الله ورسوله، وعلى تقديمها على محبة كل شيء... وعلامة ذلك: أنه إذا عرض عليه أمران: أحدهما يحبه الله ورسوله وليس لنفسه فيه هوى، والآخر تحبه نفسه وتشتهيه ولكنه يُفَوِّتُ عليه محبوبًا لله ورسوله أو ينقصه؛ فإنه إن قدّم ما تهواه نفسه على ما يحبه الله دل ذلك على أنه ظالم تارك لما يجب عليه. السعدي:٣٣٢.\nمتى تظهر محبة الله ورسوله على العبد؟\nأَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ٢٤\nوخص الجهاد بالذكر من عموم ما يحبه الله منهم تنويها بشأنه، ولأن ما فيه من الخطر على النفوس ومن إنفاق الأموال ومفارقة الإلف، جعله أقوى مظنة للتقاعس عنه؛ لا سيما والسورة نزلت عقب غزوة تبوك التي تخلف عنها كثير من المنافقين وبعض المسلمين. ابن عاشور:١٠/١٥٣.\nلماذا خص الجهاد بالذكر في الآية الكريمة؟\nلَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ\nيذكر تعالى للمؤمنين فضله عليهم، وإحسانه لديهم في نصره إياهم في مواطن كثيرة من غزواتهم مع رسوله، وأن ذلك من عنده تعالى وبتأييده وتقديره، لا بعددهم ولا بُعَددهم، ونبههم على أن النصر من عنده. ابن كثير:٢/٣٢٨.\nما المستفاد من إضافة النصر إلى الله -سبحانه وتعالى-؟\nوَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ ٢٥\nكانوا يومئذ [اثني] عشر ألفًا، فقال بعضهم: لن نغلب اليوم من قلة، فأراد الله إظهار عجزهم، ففرَّ الناس عن رسول الله -صلى الله عليه وسلم- حتى بقي على بغلته في نفر قليل، ثم استنصر بالله، وأخذ قبضة من تراب فرمى بها وجوه الكفار، وقال: (شاهت الوجوه)، ونادى بأصحابه فرجعوا إليه، وهزم الله الكفار. ابن جزي:١/٣٥٤.\nفي هذه الآية تربية للأمة عامة وللمجاهدين خاصة، وضح ذلك.\nوَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ ٢٥\nقال بعضهم: \"لن نغلب اليوم عن قلة\"؛ فوكلوا إلى هذه الكلمة، فكان ما ذكرناه من الهزيمة في الابتداء إلى أن تراجعوا. البغوي:١٠/١٤٩.\nبيّن خطورة العجب بالنفس والإمكانات على الأفراد والجماعات."],[191,"§التوبة\nwords\nعَيلَةًفَقرًا.\nيُضَاهِئُونَيُشَابِهُونَ.\nأَنَّى يُؤفَكُونَكَيفَ يُصرَفُونَ عَنِ الحَقِّ؟!\ndeeds\nتعبد لله تعالى بهذين الاسمين العظيمين بالدعـاء بهما، فقـل: \"يا غفـور اغفر لي، يا رحيم ارحمني\".\nتعلم أحكام التعامل مع الكفار من أهل الذمة وغيرهم.\nأرسل رسالة تبين فيها أن من التوكل ترك الكسب الحرام مخافة الله وثقة بوعده سبحانه.\nguid\nالخوف من الفاقة والفقر لا يمنعان المؤمن من امتثال أمر ربّه؛ فإن الله تعالى بشّر من امتثل أمره بالغنى.\nطلب العلم ليس مبررًا للفقر أو أن تكون عالة على الآخرين؛ فكم من عالمٍ وعابدٍ كان من أغنى الناس.\nلا تطع العلماء في معصية الله تعالى، ولا تتعصب لشيخ أو مربٍّ بحيث ترد الحق لأجله، وأخلص اتباعك لشرع الله تعالى وحده، واحرص على معرفة الدليل.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ\nأي: خبثاء في عقائدهم وأعمالهم، وأي نجاسة أبلغ ممن كان يعبد مع الله آلهة لا تنفع ولا تضر ولا تغني عنهم شيئًا؟! وأعمالهم ما بين محاربة لله، وصد عن سبيل الله، ونصر للباطل، ورد للحق، وعمل بالفساد في الأرض لا في الصلاح. السعدي:٣٣٣.\nما وجه نجاسة المشركين؟\nوَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ ٢٨\n﴿وَإِنۡ خِفۡتُمۡ عَيۡلَةً﴾ أي: فقرًا؛ كان المشركون يجلبون الأطعمة إلى مكة، فخاف الناس قلة القوت بها إذ مُنِع المشركون منها؛ فوعدهم الله بأن يغنيهم من فضله، فأسلمت العرب كلها، وتمادى جلب الأطعمة إلى مكة، ثم فتح الله سائر الأمصار. ابن جزي:١/٣٥٥.\nما توجيهك لمن يبرر لنفسه أكل المال الحرام بحجة خوف الفقر؟\nوَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ\nتعليق للإغناء بالمشيئة؛ لأن الغنى في الدنيا ليس من لوازم الإيمان، ولا يدل على محبة الله، فلهذا علَّقه الله بالمشيئة؛ فإن الله يعطي الدنيا من يحب ومن لا يحب، ولا يعطي الإيمان والدين إلا من يحب. السعدي:٣٣٣.\nلماذا علق الله الإغناء بالمشيئة؟\nقَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ ٢٩\n﴿عَن يَدٍ﴾ أي: عن قهر وذل... وقال ابن عباس -رضي الله عنهما-: \"يعطونها بأيديهم، ولا يرسلون بها على يد غيرهم\"... وقيل: عن إقرار بإنعام المسلمين عليهم بقبول الجزية منهم. البغوي:٢/٢٦٨.\nبيِّن عزة الإسلام وذلة الكفار في إعطاء الجزية.\nوَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ\nأي: لا يدينون الدين الصحيح، وإن زعموا أنهم على دين فإنه دين غير الحق؛ لأنه ما بين دِينٍ مُبَدَّلٍ وهو الذي لم يشرعه الله أصلًا، وإما دين منسوخ قد شرعه الله ثم غَيَّرَه بشريعة محمد -صلى الله عليه وسلم-، فيبقى التمسك به بعد النسخ غير جائز. السعدي:٣٣٤.\nبطلان دين أهل الكتاب من جهتين، فما هما؟\nٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ\nروي عن عدي بن حاتم -رضي الله عنه- قال: أتيت رسول الله -صلى الله عليه وسلم- وفي عنقي صليب من ذهب، فقال لي: «يا عدي اطرح هذا الوثن من عنقك»، فطرحته، ثم انتهيت إليه وهو يقرأ: ﴿ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابًا مِّن دُونِ ٱللَّهِ﴾، حتى فرغ منها، قلت: إنا لسنا نعبدهم، فقال: «أليس يحرمون ما أحل الله فتحرمونه، ويحلون ما حرم الله فتستحلونه؟» قال: فقلت: بلى، قال: «فتلك عبادتهم». قال عبد الله بن المبارك: وهل بدل الدين إلا الملوك***وأحبار سوء ورهبانها. البغوي:٢/٢٧٣.\nكيف صار العلماء والعباد أربابًا لأقوامهم من دون الله تعالى؟\nٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ\nكانوا يأخذون بأقوال أحبارهم ورهبانهم المخالفة لما هو معلوم بالضرورة أنه من الدين؛ فكانوا يعتقدون أن أحبارهم ورهبانهم يحللون ما حرم الله ويحرمون ما أحل الله، وهذا مُطَّرد في جميع أهل الدينين... فحصل من مجموع أقوال اليهود والنصارى أنهم جعلوا لبعض أحبارهم ورهبانهم مرتبة الربوبية في اعتقادهم؛ فكانت الشناعة لازمة للأمتين ولو كان من بينهم من لم يقل بمقالهم كما زعم عدي بن حاتم؛ فإن الأمة تؤاخذ بما يصدر من أفرادها إذا أقرته ولم تنكره. ابن عاشور:١٠/١٧٠.\nمتى يقع الشرك في باب التحليل والتحريم؟"],[192,"§التوبة\nwords\nلِيُظهِرَهُلِيُعلِيَهُ.\nأَربَعَةٌ حُرُمٌحَرَّمَ اللهُ فِيهَا القِتَالَ، وَهِيَ: ذُو القَعدَةِ، وَذُو الحِجَّةِ، وَالمُحَرَّمُ، وَرَجَبٌ.\ndeeds\nراجع زكاة أموالك، وتصدق بصدقة مستحبة.\nمن أقوى أسباب انتشار الشرك والبدع: الأموال التي تدفع لأئمتها المضلين.\nابدأ من اليوم بإظهار الأشهر الهجرية في تعاملاتك قدر استطاعتك؛ فهي المقدمة عند الله، وهي من مظاهر الدين الإسلامي.\nguid\nبيان عداء قادة اليهود والنصارى للإسلام، وتعاونهم على إفساده وإفساد أهله.\nبشرى للمسلمين بأن الإسلام سيصبح هو الدين الذي يعبد الله به في الأرض لا غيره.\nانظر كيف يكون المال جحيمًا على أصحابه يوم القيامة إذا لم يؤدوا الزكاة الواجبة.\nrefl\nيُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ٣٢\nإضافة النور إلى اسم الجلالة إشارة إلى أن محاولة إطفائه عبث، وأن أصحاب تلك المحاولة لا يبلغون مرادهم. ابن عاشور:١٠/١٧٢.\nما فائدة إضافة النور إلى الله تعالى؟\nهُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ٣٣\nوإظهاره: جعله أعلى الأديان وأقواها؛ حتى يعم المشارق والمغارب. ابن جزي:١/٣٥٦.\nماذا تقول لمن أصابه اليأس من انتصار أهل الإسلام من خلال هذه الآية؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ\nوالمقصود: التحذير من علماء السوء، وعباد الضلال؛ كما قال سفيان بن عيينة: \"من فسد من علمائنا كان فيه شبه من اليهود، ومن فسد من عبادنا كان فيه شبه من النصارى\". ابن كثير:٢/٣٣٥.\nما المقصود من التحذير من حال الأحبار والرهبان؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ ٣٤\nفإن الناس عالةٌ على العلماء، وعلى العباد، وعلى أرباب الأموال؛ فإذا فسدت أحوال هؤلاء فسدت أحوال الناس. ابن كثير:٢/٣٣٥.\nلِمَ خص الله الأحبار -وهم العلماء-، والرهبان -وهم العباد-، والأغنياء بالتحذير؟\nوَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ ٣٤ يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ ٣٥\nيُقال: \"من أحب شيئًا وقَدَّمَه على طاعة الله عُذِّبَ به\"، وهؤلاء لمَّا كان جمع هذه الأموال آثر عندهم من رضا الله عنهم عذبوا بها... هذه الأموال لمَّا كانت أعز الأموال على أربابها كانت أضر الأشياء عليهم في الدار الآخرة. ابن كثير:٢/٣٣٦.\nمن أحب شيئًا وقَدَّمَه على طاعة الله عُذِّبَ به، وضح ذلك من خلال الآية.\nإِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ\nهذه الآية تدل على أن الواجب تعليق الأحكام من العبادات وغيرها؛ إنَّما يكون بالشهور والسنين التي تعرفها العرب دون الشهور التي تعتبرها العجم والروم والقبط. القرطبي:١٠/١٩٧.\nكثرت الدعوة لترك الشهور العربية، والاعتياض عنها بالشهور الأجنبية؛ فما التوجيه القرآني في ذلك؟\nوَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ٣٦\n﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾؛ فلتحرصوا على استعمال تقوى الله في سركم وعلنكم، والقيام بطاعته، خصوصًا عند قتال الكفار؛ فإنه في هذه الحال ربما ترك المؤمن العمل بالتقوى في معاملة الكفار الأعداء المحاربين. السعدي:٣٣٦.\nلماذا أُمِرَ بالتقوى بعد الأمر بمقاتلة الكفار؟"],[193,"§التوبة\nwords\nالنَّسِيءُالتَّأخِيرُ لِحُرمَةِ شَهرٍ إِلَى شَهرٍ آخَرَ.\nلِيُوَاطِئُوالِيُوَافِقُوا.\nعِدَّةَعَدَدَ.\nاثَّاقَلتُمتَبَاطَأتُم، وَتَكَاسَلتُم.\nإِلاَّ تَنفِرُواإِلاَّ تَخرُجُوا لِلجِهَادِ.\ndeeds\nألق كلمة، أو أرسل رسالة عن خطر التحايل على الشريعة، وأهمية مراقبة الله.\nتذكر أسماء ثلاث دول أو أمم استبدل الله بها غيرها لمَّا استبدلوا بشرع الله هوى أنفسهم، ثم استعذ برضى الله من سخطه، وبمعافاته من عقوبته، ومن تحول عافيته وفجاءة نقمته.\nابحث عن سنة من سنن النبي لم تطبقها، وطبقها.\nguid\nعلى المجتمع أن يراجع العادات الدخيلة عليه بين آونة وأخرى؛ فلعل بعض هذه العادات يكون قبيحًا وقد استحسنها مع كثرة ممارستها.\nاعلم أن من سنة الله تعالى في خلقه الاستبدال؛ فمن بدّل وضيّع أذهبه الله وأتى بخير منه.\nالحزن يفُتُّ العضد، ويضعف العزيمة والقلب، فعلى المسلم أن يُذهبه عنه وعن من حوله قدر الإمكان.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ ٣٨\nعاتبهم الله على إيثار الراحة في الدنيا على الراحة في الآخرة؛ إذ لا تُنال راحة الآخرة إلا بنصب الدنيا. القرطبي:١٠/٢٠٨.\nكيف تُنال راحة الآخرة؟\nإِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا\nفإن عدم النفير في حال الاستنفار من كبائر الذنوب الموجبة لأشد العقاب؛ لما فيها من المضار الشديدة: فإن المتخلف قد عصى الله تعالى وارتكب لنهيه، ولم يساعد على نصر دين الله، ولا ذَبَّ عن كتاب الله وشرعه، ولا أعان إخوانه المسلمين على عدوهم الذي يريد أن يستأصلهم ويمحق دينهم، وربما اقتدى به غيره من ضعفاء الإيمان، بل رُبَّما فَتَّ في أعضاد من قاموا بجهاد أعداء الله. السعدي:٣٣٧.\nما خطورة عدم النفرة عند الاستنفار في سبيل الله؟\nإِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ٣٩\nقوله تعالى: ﴿إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمًا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ﴾؛ قد يكون العذاب من عنده وقد يكون بأيدي العباد، فإذا ترك الناس الجهاد في سبيل الله فقد يبتليهم بأن يوقع بينهم العداوة حتى تقع بينهم الفتنة كما هو الواقع؛ فإن الناس إذا اشتغلوا بالجهاد في سبيل الله جمع الله قلوبهم وألّف بينهم وجعل بأسهم على عدو الله وعدوهم. ابن تيمية:٣/٣٥٠.\nبيِّن أثر ترك الجهاد، مع توضيح نوعي عذاب المتخلف عنه؛ مستدلًا بأثر الجهاد في جمع الكلمة، وأثر تركه في الفرقة والتناحر.\nإِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَ\nهذا إعلام من الله -عز وجل- أنه المتكفل بنصر رسوله -صلى الله عليه وسلم-، وإعزاز دينه؛ أعانوه، أو لم يعينوه، وأنه قد نصره عند قلة الأولياء، وكثرة الأعداء؛ فكيف به اليوم وهو في كثرة من العدد والعُدد. البغوي:٢/٢٨٢.\nيظن بعض المسلمين أن الدين محتاج إليه، بين التوجيه القرآني في هذا الأمر.\nإِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ\n﴿إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ﴾: لا يختص بمصاحبته في الغار؛ بل هو صاحبه المطلق، الذي كمل في الصحبة كمالًا لم يشركه فيه غيره، فصار مختصًّا بالأكملية من الصحبة. ابن تيمية:٣/٣٥٢.\nاختص أبو بكر الصديق -رضي الله عنه- بالأكملية في الصحبة، بين ذلك.\nلَا تَحۡزَنۡ\nالحزن قد يعرض لخواص عباد الله الصديقين، مع أن الأَولَى إذا نزل بالعبد أن يسعى في ذهابه عنه؛ فإنه مضعف للقلب، مُوهِنٌ للعزيمة. السعدي:٣٣٨.\nما خطورة الحزن على المسلم؟ وكيف يتعامل معه؟\nوَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ\nفدين الله هو الظاهر العالي على سائر الأديان بالحجج الواضحة، والآيات الباهرة، والسلطان الناصر. السعدي:٣٣٨.\nما الوسائل التي يعلو بها دين الإسلام على غيره؟"],[194,"§التوبة\nwords\nعَرَضًا قَرِيبًامَتَاعًا مِنَ الدُّنيَا، سَهلَ المَأخَذِ.\nالشُّقَّةُالمَسَافَةُ الَّتِي تُقطَعُ بِمَشَقَّةٍ.\nانبِعَاثَهُمخُرُوجَهُم لِلجِهَادِ مَعَكَ.\nفَثَبَّطَهُمثَقَّلَ عَلَيهِمُ الخُرُوجَ.\nخَبَالًافَسَادًا، وَاضطِرَابًا.\nوَلأَوضَعُوا خِلاَلَكُملَأَسرَعُوا السَّيرَ بَينَكُم بِالنَّمِيمَةِ.\nيَبغُونَكُمُ الفِتنَةَيَطلُبُونَ فِتنَتَكُم، وَفَسَادَ ذَاتِ بَينِكُم.\ndeeds\nتبرع بشيء من مالك للجهات الخيرية؛ فهو من الجهاد بالمال.\nاستعذ بالله من العجز والكسل؛ فإنهما يحرمان الإنسان من العبادة.\nضع اليوم خطة، وجهز استعدادت لفعل الخير، واجعله يشغل حيزًا من تفكيرك، وأن لا يحرمك منه بسبب ذنوبك.\nguid\nمن الجهاد: الجهاد بالمال.\nمشروعية العتاب للمحب.\nإرادة الخير لا تكفي حتى يدل عليها الاستعداد بالعمل.\nrefl\nٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ٤١\nوالجهاد بالمال مقدم على الجهاد بالنفس، كما في قوله تعالى: ﴿وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ﴾... فإن المجاهد بالمال قد أخرج ماله حقيقة لله، والمجاهد بنفسه لله يرجو النجاة. ابن تيمية:٣/٣٧٣.\nما أهمية الجهاد بالمال؟ بين ذلك من خلال الآية.\nوَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ٤١\nأي: هذا خير لكم في الدنيا والآخرة؛ لأنكم تغرمون في النفقة قليلًا؛ فيغنمكم الله أموال عدوكم في الدنيا، مع ما يدخر لكم من الكرامة في الآخرة. ابن كثير:٢/٣٤٤.\nخيرية الجهاد تكون دنيوية وأخروية، وضِّح ذلك بمثال.\nعَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ ٤٣\nقال سفيان بن عيينة: \"انظروا إلى هذا اللطف؛ بدأ بالعفو قبل أن يعيّره بالذنب\". البغوي:٢/٢٨٩.\nكيف نتعلم أدب العتاب من أسلوب القرآن الكريم؟\nلَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ\nأخبر أن المؤمنين بالله واليوم الآخر لا يستأذنون في ترك الجهاد بأموالهم وأنفسهم؛ لأن ما معهم من الرغبة في الخير والإيمان يحملهم على الجهاد من غير أن يحثهم عليه حاثّ، فضلًا عن كونهم يستأذنون في تركه من غير عذر. السعدي:٣٣٨-٣٣٩.\nلماذا كان المؤمنون حقيقةً لا يعتذرون عن الجهاد؟\nوَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ ٤٦\nأي: لو أرادوا الجهاد لتأهبوا أهبة السفر؛ فتركهم الاستعداد دليل على إرادتهم التخلف. القرطبي:١٠/٢٢٩.\nما علامة الصدق في إرادة العبادة؟\nلَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ ٤٧\n﴿لَوۡ خَرَجُواْ﴾ يعني: المنافقين، (فيكم) أي: معكم، ﴿مَّا زَادُوكُمۡ إِلَّا خَبَالًا﴾ أي: فسادًا وشرًا، ومعنى الفساد: إيقاع الجبن والفشل بين المؤمنين بتهويل الأمور. (ولأوضعوا): أسرعوا، (خلالكم) أي: وسطكم؛ بإيقاع العداوة والبغضاء بينكم بالنميمة، ونقل الحديث من البعض إلى البعض. البغوي:٢/٢٨٩.\nبيّن أثر المنافقين في النميمة والإفساد.\nوَفِيكُمۡ سَمَّٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ ٤٧\nفأخبر أن في المؤمنين من يستجيب للمنافقين، ويقبل منهم؛ فإذا كان هذا في عهد النبي -صلى الله عليه وسلم-، كان استجابة بعض المؤمنين لبعض المنافقين فيما بعده أولى. ابن تيمية:٣/٣٧٤.\nهل خطر النفاق خاص بزمن النبي -صلى الله عليه وسلم-؟ وضح ذلك."],[195,"§التوبة\nwords\nوَقَلَّبُوا لَكَ الأُمُورَدَبَّرُوا الحِيَلَ.\nتَرَبَّصُونَتَنتَظِرُونَ.\nإِحدَى الحُسنَيَينِالشَّهَادَةَ أَوِ النَّصرَ.\ndeeds\nاجمع صفات المنافقين التي ذكرها الله تعالى في السورة، ثم احذر الوقوع فيها.\nتدبر هذه الآية وتمثل مقاصدها.\nسل الله تعالى الشهادة بصدق يبلغك منازل الشهداء.\nguid\nتقليب الأمور، وتغيير الحقائق من أبرز أساليب المنافقين ومن انخدع بهم، فافقه طريقتهم وأسلوبهم، واحذر الوقوع في خداعهم.\nالمؤمن يفرح بظهور أمر الله وبيان الحق، أما المنافق فيكره ذلك.\nمن علامات صلاة المؤمن: أنه يأتيها وهو محب لها لما فيها من الخيرات الكثيرة له.\nrefl\nلَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ ٤٨\n﴿وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ﴾ أي: أداروا الأفكار، وأعملوا الحيل في إبطال دعوتكم وخذلان دينكم، ولم يقصروا في ذلك، ﴿حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ﴾؛ فبطل كيدهم، واضمحل باطلهم، فحقيق بمثل هؤلاء أن يحذِّر الله عباده المؤمنين منهم. السعدي:٣٣٩.\nمكر المنافقين ومكائدهم كبيرة مع أن مصيرها إلى الفشل، وضح ذلك.\nأَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ\nفإنه على تقدير صدق هذا القائل في قصده، فإن في التخلف مفسدة كبرى، وفتنة عظمى محققة؛ وهي معصية الله، ومعصية رسوله، والتجرؤ على الإثم الكبير، والوزر العظيم، وأمَّا الخروج فمفسدة قليلة بالنسبة للتخلف؛ وهي متوهمة، مع أن هذا القائل قصده التخلف لا غير. السعدي:٣٣٩.\nللمنافقين مقاييس في المعصية تختلف عن مقاييس المؤمنين، وضحها.\nإِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ ٥٠\n﴿إِن تُصِبۡكَ حَسَنَةٌ﴾: نصرة وغنيمة، (تسؤهم): تحزنهم؛ يعني: المنافقين، ﴿وَإِن تُصِبۡكَ مُصِيبَةٌ﴾: قتل أو هزيمة، ﴿يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ﴾: حذرنا... (ويتولوا): يدبروا، ﴿وَّهُمۡ فَرِحُونَ﴾: مسرورون بما نالك من المصيبة. البغوي:٢/٢٩٠.\nهناك من يفرح بنصر الكفار، ووقوع البلاء ببعض المسلمين؛ فهل هذا من فعل المؤمنين؟\nقُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ ٥٢\n﴿قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ﴾ أي: هل تنتظرون بنا إلا إحدى أمرين: إما الظفر والنصر، وإما الموت في سبيل الله، وكل واحد من الخصلتين حسن. ﴿بِعَذَابٍ مِّنۡ عِندِهِۦٓ﴾: المصائب وما ينزل من السماء، أو عذاب الآخرة. ﴿أَوۡ بِأَيۡدِينَاۖ﴾ يعني: القتل. (فَتَرَبَّصُوا): تهديد. ابن جزي:١/٣٤٠.\nما الحسنيان اللّتان ينتظر المجاهدون إحداهما؟ وما العذابان اللّذان ينتظر الكفار أحدهما؟\nوَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ\nأفعال الكافر إذا كانت برًّا؛ كصلة القرابة، وجبر الكسير، وإغاثة الملهوف؛ لا يُثاب عليها، ولا ينتفع بها في الآخرة، بيد أنه يُطعم بها في الدنيا. القرطبي:٨/١٦١.\nقد يكون للمنافقين أعمال حسنة؛ فما الذي منعهم من الإفادة منها في الآخرة؟\nوَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ ٥٤\nففي هذا غاية الذم لمن فعل مثل فعلهم، وأنه ينبغي للعبد أن لا يأتي الصلاة إلا وهو نشيط البدن والقلب إليها، ولا ينفق إلا وهو منشرح الصدر، ثابت القلب، يرجو ذخرها وثوابها من الله وحده. السعدي:٣٤٠.\nما الصورة المثلى لإقامة الصلاة، وتقديم الصدقات؟\nوَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ ٥٤\nلأنهم يعدونها مغرمًا، ومنعها مغنمًا؛ وإذا كان المرء كذلك فهي غير متقبلة، ولا مثاب عليها. القرطبي:١٠/٢٣٩.\nما السبب في عدم قبول صدقة المنافق؟"],[196,"§التوبة\nwords\nيَفرَقُونَيَخَافُونَ.\nمَلجَأًمَأمَنًا، وَحِصنًا.\nمَغَارَاتٍكُهُوفًا فِي الجِبَالِ.\ndeeds\nراجع طريقة تعاملك؛ فلا تفرط في أموالك وأولادك وتضيعهم، ولا تبالغ في الاهتمام بهم حتى تُغضب الله من أجلهم.\nأرسل رسالة تبين فيها أن من صفات الغافلين والمنافقين أنهم ينظرون إلى من فوقهم في زينة الدنيا فقط، ولا ينظرون إلى من فوقهم في الدين.\nتأمل قصرًا قديمًا أو سيارةً فاخرةً قديمةً، وفكر في أول من ملكها: ما مصيره الآن؟ وهل سيحاسب عليها؟ وماذا يتمنى الآن؟\nguid\nزينة الدنيا قد تكون استدراجًا للكافر والفاسق، فلا تغتر بالمظاهر.\nمن صفات الغافل والمنافق أنه إذا أعطي من الدنيا رضي، وإذا منع منها سخط.\nمن صفات المنافقين: اللمز في المؤمنين -وهو العيب في خفاء- ويدرك ذلك الذكي الفطن.\nrefl\nفَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ٥٥\nفلا تعجبك أموال هؤلاء المنافقين ولا أولادهم؛ فإنه لا غبطة فيها... ومن وبالها العظيم الخطر: أن قلوبهم تتعلق بها، وإراداتهم لا تتعداها؛ فتكون منتهى مطلوبهم، وغاية مرغوبهم، ولا يبقى في قلوبهم للآخرة نصيب؛ فيوجب ذلك أن ينتقلوا من الدنيا وتزهق أنفسهم وهم كافرون. السعدي:٣٤٠.\nكيف تكون أموال المنافقين وأولادهم سببًا لكفرهم بالله العظيم؟\nفَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ٥٥\nوهكذا كل مَن أراد استدراجه سبحانهُ؛ فإنه في الغالب يكثِّرُ أموالهم وأولادهم لنحو هذا؛ لأنهم إذا رأوا زيادتهم بها على بعض المُخلِصِين ظنوا أن ذلك إنَّما هو لكرامتهم، وحسن حالتهم، فيستمرون عليها حتى يموتوا، فهو سبحانهُ لم يرد بها منحتهم، بل فتنتهم ومحنتهم. البقاعي:٣/٣٣٤.\nهل كثرة المال والولد والنعيم تدل دائمًا على رضى الله سبحانه عن الإنسان؟\nوَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ ٥٨\nفرضاهم لغير الله، وسخطهم لغير الله؛ وهكذا حال من كان متعلقًا برئاسة أو بصورة ونحو ذلك من أهواء نفسه: إن حصل له رضِيَ، وإن لم يحصل له سخِط؛ فهذا عبد ما يهواه من ذلك، وهو رقيق له؛ إذ الرق والعبودية في الحقيقة هو رق القلب وعبوديته، فما استرق القلب واستعبده فهو عبده. ابن تيمية:٣/٣٨٠.\nالرق والعبودية في الحقيقة هي عبودية القلب، بيّن ذلك من خلال الآية الكريمة.\nفَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ ٥٨\nوهذه حالة لا تنبغي للعبد: أن يكون رضاه وغضبه تابعًا لهوى نفسه الدنيوي وغرضه الفاسد، بل الذي ينبغي أن يكون هواه تبعًا لمرضاة ربه. السعدي:٣٤٠.\nكيف يكون رضى المسلم صحيحًا؟\nوَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ ٥٨\nيعيبك في أمرها وتفريقها، ويطعن عليك فيها... يعني: أن المنافقين كانوا يقولون إن محمدًا لا يعطي إلا من أحب. البغوي:٢/٢٩٣.\nما نسمعه من تشكيك في نيات العلماء والدعاة؛ هل هو أمر جديد على الأمة، أم قديم؟\nوَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ\n﴿وَيَقُولُونَ هُوَ أُذُنٌۚ﴾ أي: يسمع كل ما يقال له ويصدّقه... ﴿قُلۡ أُذُنُ خَيۡرٍ لَّكُمۡ﴾ أي: يسمع الخير والحق، ﴿وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ﴾ أي: يصدقهم؛ يقال: آمنت لك إذا صدقتك. ابن جزي:١/٢٦٢.\nلِمَ وُصف المنافقون النبي بــ (أذن)؟ وكيف رد الله عليهم؟\nوَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ ٦١\nفي الدنيا والآخرة، ومن العذاب الأليم أنه يتحتم قتل مؤذيه وشاتمه. السعدي:٣٤٢.\nاذكر صورةً من صور العذاب الأليم الدنيوي لشاتم الرسول؟"]])